import { useFactoryVideo } from '@/hooks/useFactoryVideo';
import FactoryVideoPlayer from '@/components/FactoryVideoPlayer';

export default function HomeVideoSection() {
  const { settings, homeVideo, loading } = useFactoryVideo();

  if (!settings.enabled || !settings.showOnHome) return null;
  if (loading) return null;
  if (!homeVideo.url) return null;

  return (
    <section className="w-full py-16 md:py-20 bg-background">
      <div className="max-w-5xl mx-auto px-4 md:px-6">
        <div className="text-center mb-10 md:mb-12">
          <div className="inline-block px-3 py-1 mb-4 text-xs font-medium tracking-widest uppercase text-primary border border-primary/30 rounded-sm bg-primary/5">
            Factory Tour
          </div>
          <h2 className="text-2xl md:text-3xl font-bold text-foreground tracking-tight">
            {settings.videoTitle || 'Inside Our Manufacturing Facility'}
          </h2>
          <p className="text-muted-foreground mt-3 max-w-xl mx-auto text-sm md:text-base">
            See our 40,000㎡ state-of-the-art LED lighting factory in action —
            from precision assembly to rigorous quality control.
          </p>
        </div>

        <div className="relative">
          {/* 红色光束装饰线 */}
          <div className="absolute -top-px left-1/2 -translate-x-1/2 w-24 h-px bg-gradient-to-r from-transparent via-primary to-transparent" />

          <FactoryVideoPlayer
            videoUrl={homeVideo.url}
            title={settings.videoTitle}
            posterUrl={settings.posterUrl}
            autoPlay={settings.autoPlay}
            showControls={settings.showControls}
            variant="home"
          />
        </div>

        {/* 底部装饰线 */}
        <div className="mt-10 md:mt-12 flex items-center gap-4">
          <div className="flex-1 h-px bg-gradient-to-r from-transparent to-border/50" />
          <div className="size-2 rotate-45 border border-primary/50 bg-primary/10" />
          <div className="flex-1 h-px bg-gradient-to-l from-transparent to-border/50" />
        </div>
      </div>
    </section>
  );
}
