/**
 * 页面访问追踪 Hook
 *
 * 在 App 根组件中调用一次。路由变化时：
 * - 本地 PV +1（useAnalytics / trackPageView）
 * - 向 GA4 发送 page_view 事件（如果配置了 GA4）
 */

import { useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { logger } from '@lark-apaas/client-toolkit-lite';
import { trackPageView } from './useAnalytics';
import { sendPageView } from '@/lib/analytics-injector';

export function useAnalyticsTracker() {
  const location = useLocation();

  useEffect(() => {
    const path = location.pathname;
    try {
      // 本地 PV 统计（内部已排除 /admin 路径）
      trackPageView(path);
      // GA4 page_view（内部已做未配置兜底）
      sendPageView(path);
    } catch (e) {
      logger.warn('[AnalyticsTracker] error: ' + String(e));
    }
  }, [location.pathname]);
}
