/**
 * 页脚设置上下文（全局单例）
 *
 * 🔴 根因修复：原来的 useFooterSettings 是普通函数式 hook，每个组件各自 new 一个
 * useState，用户在后台保存设置后，前台 Footer / Header / WhatsAppButton
 * 读到的仍然是旧 state，导致：
 *   - 后台修改后前台不刷新（两个独立的 state 实例）
 *   - preferRemote 模式下远程数据优先，本地修改被忽略
 *
 * 修复方案：设置提升到 Context 做单例，所有组件共享同一份 settings state。
 * 并且监听 storage 事件，跨 tab 也能同步。
 *
 * preferRemote 优化逻辑：
 *   - 如果远程数据的 updatedAt 比本地新 → 用远程数据
 *   - 如果本地数据的 updatedAt 比远程新 → 用本地数据（用户刚改过）
 *   - 远程数据为空 → 用本地数据
 */

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import { logger } from '@lark-apaas/client-toolkit-lite';
import { useRemoteDataStore } from '@/context/RemoteDataContext';
import { safeTransform, extractI18nStr, safeStr, safeBool, safeArr } from '@/lib/remote-data-safe';
import { useI18n } from '@/i18n/I18nContext';
import { createI18nText, migrateI18n, type I18nText } from '@/lib/i18n-text';

const STORAGE_KEY = '__app_ledlight_footer_settings';

export interface FooterSettings {
  brandText: I18nText;
  email: string;
  phone: string;
  address: I18nText;
  copyright: I18nText;
  certifications: string[];
  whatsappUrl: string;
  whatsappEnabled: boolean;
  facebookUrl: string;
  facebookEnabled: boolean;
  linkedinUrl: string;
  linkedinEnabled: boolean;
  twitterHandle: string;
  twitterEnabled: boolean;
  instagramUrl: string;
  instagramEnabled: boolean;
  redditUrl: string;
  redditEnabled: boolean;
  pinterestUrl: string;
  pinterestEnabled: boolean;
  snapchatUrl: string;
  snapchatEnabled: boolean;
  wechatUrl: string;
  wechatEnabled: boolean;
  wechatQrImage: string;
  headerLogo: string;
  footerLogo: string;
  updatedAt: number;
}

const DEFAULT_SETTINGS: FooterSettings = {
  brandText: createI18nText('Professional LED sensor light manufacturer from Jiujiang, China'),
  email: 'sherwin@tanjeon.com',
  phone: '+86 7928276258',
  address: createI18nText('NO.16 Jiuyuan Road, Automobile Industrial Park, Jiujiang City, Jiangxi Province, China'),
  copyright: createI18nText('Jiujiang Ouwei Industrial Co.LTD'),
  certifications: ['CE', 'RoHS', 'ISO9001', 'FCC'],
  whatsappUrl: 'https://wa.me/8617879860145?text=Hello%2C%20I%20am%20interested%20in%20your%20LED%20sensor%20lights',
  whatsappEnabled: true,
  facebookUrl: 'https://www.facebook.com/owelllightimg',
  facebookEnabled: true,
  linkedinUrl: 'https://www.linkedin.com/company/owell-industrial',
  linkedinEnabled: true,
  twitterHandle: '@owell_lightimg',
  twitterEnabled: true,
  instagramUrl: 'https://www.instagram.com/owell.industrial',
  instagramEnabled: true,
  redditUrl: '',
  redditEnabled: false,
  pinterestUrl: '',
  pinterestEnabled: false,
  snapchatUrl: '',
  snapchatEnabled: false,
  wechatUrl: 'https://mp.weixin.qq.com/',
  wechatEnabled: true,
  wechatQrImage: '',
  headerLogo: '',
  footerLogo: '',
  updatedAt: 0,
};

function deepMergeWithDefaults(saved: Partial<FooterSettings>): FooterSettings {
  const merged: FooterSettings = { ...DEFAULT_SETTINGS, ...saved };
  // 多语言字段迁移：老数据是 string 时转成 I18nText
  merged.brandText = migrateI18n(saved.brandText ?? DEFAULT_SETTINGS.brandText);
  merged.address = migrateI18n(saved.address ?? DEFAULT_SETTINGS.address);
  merged.copyright = migrateI18n(saved.copyright ?? DEFAULT_SETTINGS.copyright);
  // Ensure arrays are arrays
  if (!Array.isArray(merged.certifications)) merged.certifications = DEFAULT_SETTINGS.certifications;
  return merged;
}

/**
 * V203 字段级智能合并：远程数据 + 本地数据 → 最终展示数据
 *
 * 背景：远程 footer.json 可能是旧版本，缺少新添加的字段
 * （如 redditEnabled / pinterestEnabled / snapchatEnabled）。
 * 如果直接用远程数据整对象替换，会把用户在后台本地开启的新社媒重新关掉。
 *
 * 合并规则：
 * 1. 远程字段有「非默认值」→ 用远程值（远程数据是最新版本，用户在 GitHub 上编辑过）
 * 2. 远程字段是「默认值」且本地字段是「非默认值」→ 用本地值（用户在后台改过，远程还是老模板）
 * 3. 两边都是默认值 → 用远程（保持一致）
 * 4. updatedAt 取较大的那个
 */
function smartMergeRemoteLocal(remote: FooterSettings, local: FooterSettings): FooterSettings {
  const result: FooterSettings = { ...remote };

  // 社媒 enabled 字段：远程是 false（默认）且本地是 true → 保留本地
  const socialEnabledFields: Array<keyof FooterSettings> = [
    'redditEnabled',
    'pinterestEnabled',
    'snapchatEnabled',
    'facebookEnabled',
    'linkedinEnabled',
    'twitterEnabled',
    'instagramEnabled',
    'whatsappEnabled',
    'wechatEnabled',
  ];

  for (const field of socialEnabledFields) {
    const remoteVal = remote[field];
    const localVal = local[field];
    const defaultVal = DEFAULT_SETTINGS[field];
    // 远程是默认值（false），本地是非默认值（true）→ 保留用户的本地修改
    if (remoteVal === defaultVal && localVal !== defaultVal) {
      (result[field] as boolean) = localVal as boolean;
    }
  }

  // 社媒 URL 字段：远程为空字符串（默认）且本地非空 → 保留本地
  const socialUrlFields: Array<keyof FooterSettings> = [
    'redditUrl',
    'pinterestUrl',
    'snapchatUrl',
    'facebookUrl',
    'linkedinUrl',
    'twitterHandle',
    'instagramUrl',
    'whatsappUrl',
    'wechatUrl',
  ];

  for (const field of socialUrlFields) {
    const remoteVal = remote[field];
    const localVal = local[field];
    const defaultVal = DEFAULT_SETTINGS[field];
    // 远程是默认空值，本地有实际内容 → 保留用户的本地修改
    if (remoteVal === defaultVal && localVal !== defaultVal && typeof localVal === 'string' && localVal.trim().length > 0) {
      (result[field] as string) = localVal as string;
    }
  }

  // updatedAt 取较大的
  result.updatedAt = Math.max(remote.updatedAt || 0, local.updatedAt || 0);

  return result;
}

function readLocalFooterSettings(): FooterSettings {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved) as Partial<FooterSettings>;
      return deepMergeWithDefaults(parsed);
    }
  } catch (err) {
    logger.error('[FooterSettings] Failed to read local settings:', String(err));
  }
  return { ...DEFAULT_SETTINGS, updatedAt: 0 };
}

interface FooterSettingsContextValue {
  /** 本地存储的设置（始终是 localStorage 的最新值） */
  settings: FooterSettings;
  /** 是否正在加载（首帧同步读取，始终为 false） */
  loading: boolean;
  /** 是否使用了远程数据（preferRemote 模式下远程数据比本地新时为 true） */
  isUsingRemoteData: boolean;
  /** 更新设置（同时更新 state 和 localStorage，并派发 CustomEvent） */
  updateSettings: (data: Partial<FooterSettings>) => boolean;
  /** 重置为默认值 */
  resetToDefaults: () => boolean;
  /** 根据 preferRemote 选项获取最终展示用的设置 */
  getDisplaySettings: (preferRemote: boolean) => FooterSettings;
}

const FooterSettingsContext = createContext<FooterSettingsContextValue | null>(null);

export function FooterSettingsProvider({ children }: { children: ReactNode }) {
  // 同步初始化：直接读 localStorage 作为初始值
  const [settings, setSettings] = useState<FooterSettings>(() => readLocalFooterSettings());

  // 远程数据（全局只读一份）
  const remoteData = useRemoteDataStore<Partial<FooterSettings>>('footer');
  const { language } = useI18n();

  // 计算合并后的远程设置（带默认值兜底 + try-catch 防崩溃）
  const mergedRemote = useMemo<FooterSettings | null>(() => {
    if (remoteData && typeof remoteData === 'object') {
      const transformed = safeTransform('footer', () => {
        const r = remoteData as unknown as Record<string, unknown>;
        // 多语言字段按当前语言提取，非多语言字段直接读取
        const settings: Partial<FooterSettings> = {
          brandText: migrateI18n(
            (r.tagline as string | I18nText | undefined) ?? (r.brandText as string | I18nText | undefined) ?? DEFAULT_SETTINGS.brandText
          ),
          email: safeStr(r.email ?? (r.contact && (r.contact as Record<string, unknown>).email), DEFAULT_SETTINGS.email),
          phone: safeStr(r.phone ?? (r.contact && (r.contact as Record<string, unknown>).phone), DEFAULT_SETTINGS.phone),
          address: migrateI18n(
            ((r.contact && (r.contact as Record<string, unknown>).address) as string | I18nText | undefined)
            ?? (r.address as string | I18nText | undefined)
            ?? DEFAULT_SETTINGS.address
          ),
          copyright: migrateI18n(
            (r.copyright as string | I18nText | undefined) ?? DEFAULT_SETTINGS.copyright
          ),
          certifications: safeArr<string>(r.certifications).length > 0
            ? safeArr<string>(r.certifications)
            : DEFAULT_SETTINGS.certifications,
          whatsappUrl: safeStr(r.whatsappUrl ?? (r.contact && (r.contact as Record<string, unknown>).whatsapp), DEFAULT_SETTINGS.whatsappUrl),
          whatsappEnabled: safeBool(r.whatsappEnabled, DEFAULT_SETTINGS.whatsappEnabled),
          facebookUrl: safeStr(r.facebookUrl, DEFAULT_SETTINGS.facebookUrl),
          facebookEnabled: safeBool(r.facebookEnabled, DEFAULT_SETTINGS.facebookEnabled),
          linkedinUrl: safeStr(r.linkedinUrl, DEFAULT_SETTINGS.linkedinUrl),
          linkedinEnabled: safeBool(r.linkedinEnabled, DEFAULT_SETTINGS.linkedinEnabled),
          twitterHandle: safeStr(r.twitterHandle, DEFAULT_SETTINGS.twitterHandle),
          twitterEnabled: safeBool(r.twitterEnabled, DEFAULT_SETTINGS.twitterEnabled),
          instagramUrl: safeStr(r.instagramUrl, DEFAULT_SETTINGS.instagramUrl),
          instagramEnabled: safeBool(r.instagramEnabled, DEFAULT_SETTINGS.instagramEnabled),
          redditUrl: safeStr(r.redditUrl, DEFAULT_SETTINGS.redditUrl),
          redditEnabled: safeBool(r.redditEnabled, DEFAULT_SETTINGS.redditEnabled),
          pinterestUrl: safeStr(r.pinterestUrl, DEFAULT_SETTINGS.pinterestUrl),
          pinterestEnabled: safeBool(r.pinterestEnabled, DEFAULT_SETTINGS.pinterestEnabled),
          snapchatUrl: safeStr(r.snapchatUrl, DEFAULT_SETTINGS.snapchatUrl),
          snapchatEnabled: safeBool(r.snapchatEnabled, DEFAULT_SETTINGS.snapchatEnabled),
          wechatUrl: safeStr(r.wechatUrl, DEFAULT_SETTINGS.wechatUrl),
          wechatEnabled: safeBool(r.wechatEnabled, DEFAULT_SETTINGS.wechatEnabled),
          wechatQrImage: safeStr(r.wechatQrImage, DEFAULT_SETTINGS.wechatQrImage),
          headerLogo: safeStr(r.headerLogo ?? r.logo, DEFAULT_SETTINGS.headerLogo),
          footerLogo: safeStr(r.footerLogo ?? r.logo, DEFAULT_SETTINGS.footerLogo),
          updatedAt: Number(r.updatedAt ?? 0),
        };
        return deepMergeWithDefaults(settings);
      });
      if (transformed) return transformed;
      logger.warn('[Footer] remote data transform failed, falling back to local');
    }
    return null;
  }, [remoteData, language]);

  // 根据 preferRemote 和 updatedAt 比较决定展示哪份数据
  const getDisplaySettings = useCallback(
    (preferRemote: boolean): FooterSettings => {
      if (preferRemote && mergedRemote) {
        const remoteUpdatedAt = mergedRemote.updatedAt || 0;
        const localUpdatedAt = settings.updatedAt || 0;
        // 远程数据更新时间 ≥ 本地 → 用远程
        // 本地数据更新时间 > 远程 → 用本地（用户刚在后台改过）
        if (remoteUpdatedAt >= localUpdatedAt) {
          logger.info(
            `[FooterSettings] Using remote data (remote.ts=${remoteUpdatedAt} >= local.ts=${localUpdatedAt})`
          );
          // V203 修复：字段级智能合并
          // 远程数据是老版本时可能缺少新字段（如 reddit/pinterest/snapchat），
          // 如果直接整对象替换，会把本地已开启的新社媒重新关掉。
          // 改为：远程有值的字段用远程的，远程为空/默认值且本地有用户修改的字段保留本地值。
          return smartMergeRemoteLocal(mergedRemote, settings);
        }
        logger.info(
          `[FooterSettings] Using local data (local.ts=${localUpdatedAt} > remote.ts=${remoteUpdatedAt}) — user has edited settings locally`
        );
      }
      return settings;
    },
    [mergedRemote, settings]
  );

  // isUsingRemoteData：preferRemote 为 true 且实际使用了远程数据
  const isUsingRemoteData = useMemo(() => {
    if (!mergedRemote) return false;
    const remoteUpdatedAt = mergedRemote.updatedAt || 0;
    const localUpdatedAt = settings.updatedAt || 0;
    return remoteUpdatedAt >= localUpdatedAt;
  }, [mergedRemote, settings]);

  // 监听 storage 事件（跨 tab 同步）
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key !== STORAGE_KEY || !e.newValue) return;
      try {
        const parsed = JSON.parse(e.newValue) as Partial<FooterSettings>;
        const merged = deepMergeWithDefaults(parsed);
        logger.info(
          `[FooterSettings] Storage event received from another tab, updatedAt=${merged.updatedAt}`
        );
        setSettings(merged);
      } catch (err) {
        logger.error('[FooterSettings] Failed to parse storage event:', String(err));
      }
    };

    const handleCustomChange = (e: Event) => {
      const detail = (e as CustomEvent<FooterSettings>).detail;
      if (detail) {
        logger.info(
          `[FooterSettings] CustomEvent received, updatedAt=${detail.updatedAt}`
        );
        setSettings(detail);
      }
    };

    window.addEventListener('storage', handleStorageChange);
    window.addEventListener('footer-settings-change', handleCustomChange);
    return () => {
      window.removeEventListener('storage', handleStorageChange);
      window.removeEventListener('footer-settings-change', handleCustomChange);
    };
  }, []);

  // 更新设置
  const updateSettings = useCallback((data: Partial<FooterSettings>): boolean => {
    try {
      const next: FooterSettings = {
        ...settings,
        ...data,
        updatedAt: Date.now(),
      };
      setSettings(next);
      localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      window.dispatchEvent(new CustomEvent('footer-settings-change', { detail: next }));
      logger.info(
        `[FooterSettings] Settings saved successfully, updatedAt=${next.updatedAt}, fields=${Object.keys(data).join(',')}`
      );
      return true;
    } catch (err) {
      logger.error('[FooterSettings] Failed to save settings:', String(err));
      return false;
    }
  }, [settings]);

  // 重置为默认值
  const resetToDefaults = useCallback((): boolean => {
    try {
      const def = { ...DEFAULT_SETTINGS, updatedAt: Date.now() };
      setSettings(def);
      localStorage.setItem(STORAGE_KEY, JSON.stringify(def));
      window.dispatchEvent(new CustomEvent('footer-settings-change', { detail: def }));
      logger.info('[FooterSettings] Settings reset to defaults');
      return true;
    } catch (err) {
      logger.error('[FooterSettings] Failed to reset settings:', String(err));
      return false;
    }
  }, []);

  const value = useMemo<FooterSettingsContextValue>(
    () => ({
      settings,
      loading: false,
      isUsingRemoteData,
      updateSettings,
      resetToDefaults,
      getDisplaySettings,
    }),
    [settings, isUsingRemoteData, updateSettings, resetToDefaults, getDisplaySettings]
  );

  return (
    <FooterSettingsContext.Provider value={value}>
      {children}
    </FooterSettingsContext.Provider>
  );
}

/**
 * useFooterSettings hook（从 Context 读取，全局单例）
 *
 * 保持原有 API 兼容：
 *   const { settings, loading, updateSettings, resetToDefaults, isUsingRemoteData } = useFooterSettings({ preferRemote: true });
 *
 * 注意：preferRemote 逻辑已优化——
 *   如果本地设置的 updatedAt 比远程数据新（用户刚在后台改过），优先显示本地设置。
 */
export function useFooterSettings(options?: { preferRemote?: boolean }) {
  const ctx = useContext(FooterSettingsContext);
  if (!ctx) {
    throw new Error('useFooterSettings must be used within FooterSettingsProvider');
  }

  const preferRemote = options?.preferRemote ?? false;
  const displaySettings = preferRemote
    ? ctx.getDisplaySettings(true)
    : ctx.settings;

  return {
    settings: displaySettings,
    loading: ctx.loading,
    updateSettings: ctx.updateSettings,
    resetToDefaults: ctx.resetToDefaults,
    isUsingRemoteData: preferRemote && ctx.isUsingRemoteData,
  };
}

export default FooterSettingsProvider;
