import { useState } from 'react';
import { motion } from 'framer-motion';
import { ChevronDown, HelpCircle } from 'lucide-react';
import { useI18n } from '@/i18n/I18nContext';
import { useSeo } from '@/hooks/useSeo';
import { useFaqs } from '@/hooks/useFaqs';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { getI18nValue } from '@/lib/i18n-text';
import { Button } from '@/components/ui/button';
import { useNavigate } from 'react-router-dom';

export default function FaqPage() {
  const { t, language } = useI18n();
  const { faqs, loading } = useFaqs({ preferRemote: true });
  const navigate = useNavigate();
  const [openId, setOpenId] = useState<string | null>(faqs[0]?.id ?? null);

  useSeo({
    title: t('seo.faqTitle'),
    description: t('seo.faqDescription'),
    keywords: t('seo.faqKeywords'),
    type: 'article',
    pageKey: 'faq',
    schema: {
      '@context': 'https://schema.org',
      '@type': 'FAQPage',
      mainEntity: faqs.map((faq) => ({
        '@type': 'Question',
        name: getI18nValue(faq.question, language),
        acceptedAnswer: {
          '@type': 'Answer',
          text: getI18nValue(faq.answer, language),
        },
      })),
    },
  });

  const toggleFaq = (id: string) => {
    setOpenId((prev) => (prev === id ? null : id));
  };

  return (
    <div className="min-h-[60vh]">
      {/* Breadcrumb */}
      <div className="w-full border-b border-border bg-card/20">
        <div className="max-w-7xl mx-auto px-4 md:px-6 py-3">
          <PageBreadcrumb
            firstItem={{ label: t('nav.home'), href: '/', icon: 'home' }}
            items={[{ label: t('faq.title') }]}
          />
        </div>
      </div>

      {/* Hero Section */}
      <section className="relative py-16 md:py-20 bg-gradient-to-b from-primary/10 via-background to-background border-b border-border/60 overflow-hidden">
        <div className="absolute top-0 left-0 right-0 h-[2px] bg-gradient-to-r from-transparent via-primary/80 to-transparent" />
        <div className="max-w-4xl mx-auto px-4 md:px-6 text-center">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-primary/10 border border-primary/30 text-primary text-sm font-medium mb-6"
          >
            <HelpCircle className="size-4" />
            <span>FAQ</span>
          </motion.div>
          <motion.h1
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.1 }}
            className="text-4xl md:text-5xl font-bold text-foreground tracking-tight mb-4"
            style={{ fontFamily: "'Rajdhani', 'Inter', sans-serif" }}
          >
            {t('faq.title')}
          </motion.h1>
          <motion.p
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.2 }}
            className="text-base md:text-lg text-muted-foreground max-w-2xl mx-auto leading-relaxed"
          >
            {t('faq.subtitle')}
          </motion.p>
        </div>
      </section>

      {/* FAQ List */}
      <section className="py-16 md:py-20">
        <div className="max-w-3xl mx-auto px-4 md:px-6">
          {loading ? (
            <div className="text-center text-muted-foreground py-12">Loading...</div>
          ) : (
            <div className="space-y-3">
              {faqs.map((faq, index) => {
                const isOpen = openId === faq.id;
                const question = getI18nValue(faq.question, language);
                const answer = getI18nValue(faq.answer, language);

                return (
                  <motion.div
                    key={faq.id}
                    initial={{ opacity: 0, y: 16 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.4, delay: index * 0.05 }}
                    className={`group border rounded-sm overflow-hidden transition-all duration-300 ${
                      isOpen
                        ? 'border-primary/40 bg-card/80'
                        : 'border-border/60 bg-card/30 hover:border-border hover:bg-card/50'
                    }`}
                  >
                    <button
                      onClick={() => toggleFaq(faq.id)}
                      className="w-full flex items-center justify-between gap-4 p-5 md:p-6 text-left"
                    >
                      <div className="flex items-start gap-4 min-w-0">
                        <span
                          className={`shrink-0 w-8 h-8 rounded-sm flex items-center justify-center text-sm font-bold transition-colors ${
                            isOpen
                              ? 'bg-primary text-primary-foreground'
                              : 'bg-primary/10 text-primary'
                          }`}
                        >
                          {index + 1}
                        </span>
                        <h3
                          className={`text-base md:text-lg font-semibold leading-snug transition-colors ${
                            isOpen ? 'text-foreground' : 'text-foreground/90'
                          }`}
                        >
                          {question}
                        </h3>
                      </div>
                      <ChevronDown
                        className={`size-5 shrink-0 transition-all duration-300 ${
                          isOpen ? 'rotate-180 text-primary' : 'text-muted-foreground'
                        }`}
                      />
                    </button>
                    {isOpen && (
                      <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: 'auto', opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        transition={{ duration: 0.3 }}
                      >
                        <div className="px-5 md:px-6 pb-6 pl-[72px] md:pl-[88px]">
                          <div className="border-l-2 border-primary/30 pl-4">
                            <p className="text-muted-foreground leading-relaxed whitespace-pre-line">
                              {answer}
                            </p>
                          </div>
                        </div>
                      </motion.div>
                    )}
                  </motion.div>
                );
              })}
            </div>
          )}

          {/* CTA Banner */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5 }}
            className="mt-16 p-6 md:p-10 border border-border/60 rounded-sm bg-gradient-to-r from-primary/10 via-card/50 to-card/30 relative overflow-hidden"
          >
            <div className="absolute top-0 left-0 right-0 h-[2px] bg-gradient-to-r from-transparent via-primary/60 to-transparent" />
            <div className="relative z-10 flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
              <div>
                <h3 className="text-xl md:text-2xl font-bold text-foreground mb-2" style={{ fontFamily: "'Rajdhani', 'Inter', sans-serif" }}>
                  {t('faq.ctaTitle')}
                </h3>
                <p className="text-muted-foreground">{t('faq.ctaSubtitle')}</p>
              </div>
              <Button
                onClick={() => navigate('/contact')}
                size="lg"
                className="bg-primary hover:bg-primary/90 text-primary-foreground shadow-[0_0_20px_rgba(230_57_70_0.25)] hover:shadow-[0_0_28px_rgba(230_57_70_0.4)] transition-shadow duration-300"
              >
                {t('nav.getQuote')}
              </Button>
            </div>
          </motion.div>
        </div>
      </section>
    </div>
  );
}
