import { useState, useEffect, useCallback } from 'react';
import { logger } from '@lark-apaas/client-toolkit-lite';
import { createI18nText, migrateI18n, type I18nText } from '@/lib/i18n-text';

const STORAGE_KEY = '__app_ledlight_quote_section_v1';
const STORAGE_VERSION = 1;

export interface IQuoteFeature {
  id: string;
  icon: string;
  text: I18nText;
}

export interface IQuoteSectionData {
  title: I18nText;
  subtitle: I18nText;
  features: IQuoteFeature[];
  showOnHomepage: boolean;
}

const DEFAULT_DATA: IQuoteSectionData = {
  title: createI18nText('Get a Free Quote', '免费获取报价', 'Obtén un presupuesto gratuito', '無料見積もりを取得'),
  subtitle: createI18nText(
    'Tell us your requirements and we will respond within 12 hours.',
    '告诉我们您的需求，我们将在12小时内回复。',
    'Cuéntanos tus requisitos y responderemos en 12 horas.',
    'ご要望をお聞かせください。12時間以内にご返信いたします。'
  ),
  features: [
    {
      id: 'f1',
      icon: 'Clock',
      text: createI18nText('12-hour fast response', '12小时快速响应', 'Respuesta rápida en 12 horas', '12時間以内の迅速な対応'),
    },
    {
      id: 'f2',
      icon: 'CheckCircle2',
      text: createI18nText('Competitive factory direct price', '有竞争力的工厂直供价格', 'Precio competitivo directo de fábrica', '競争力のある工場直販価格'),
    },
    {
      id: 'f3',
      icon: 'Package',
      text: createI18nText('Custom OEM / ODM support', '支持OEM/ODM定制', 'Soporte OEM / ODM personalizado', 'カスタムOEM / ODMサポート'),
    },
  ],
  showOnHomepage: true,
};

function migrateFeatures(raw: unknown[]): IQuoteFeature[] {
  return raw.map((item, idx) => {
    const f = item as Record<string, unknown>;
    return {
      id: String(f.id ?? `f_${idx}`),
      icon: String(f.icon ?? 'Clock'),
      text: migrateI18n(f.text as string | I18nText | undefined),
    };
  });
}

function readLocalData(): IQuoteSectionData {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed.__version === STORAGE_VERSION && parsed.data) {
        const d = parsed.data as Record<string, unknown>;
        return {
          title: migrateI18n(d.title as string | I18nText | undefined),
          subtitle: migrateI18n(d.subtitle as string | I18nText | undefined),
          features: Array.isArray(d.features) ? migrateFeatures(d.features as unknown[]) : DEFAULT_DATA.features,
          showOnHomepage: typeof d.showOnHomepage === 'boolean' ? d.showOnHomepage : true,
        };
      }
    }
  } catch {
    // ignore
  }
  return DEFAULT_DATA;
}

export function useQuoteSection() {
  const [data, setDataState] = useState<IQuoteSectionData>(() => readLocalData());

  // 监听 GitHub 数据拉取完成事件
  useEffect(() => {
    const handleGithubPulled = () => {
      try {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (saved) {
          const parsed = JSON.parse(saved);
          if (parsed.__version === STORAGE_VERSION && parsed.data) {
            const d = parsed.data as Record<string, unknown>;
            setDataState({
              title: migrateI18n(d.title as string | I18nText | undefined),
              subtitle: migrateI18n(d.subtitle as string | I18nText | undefined),
              features: Array.isArray(d.features) ? migrateFeatures(d.features as unknown[]) : DEFAULT_DATA.features,
              showOnHomepage: typeof d.showOnHomepage === 'boolean' ? d.showOnHomepage : true,
            });
            logger.info('[QuoteSection] Refreshed from localStorage after GitHub pull');
          }
        }
      } catch (err) {
        logger.warn('[QuoteSection] Failed to refresh after GitHub pull:', String(err));
      }
    };

    window.addEventListener('app-ledlight-quote-section-github-pulled', handleGithubPulled);
    return () => {
      window.removeEventListener('app-ledlight-quote-section-github-pulled', handleGithubPulled);
    };
  }, []);

  const persist = (d: IQuoteSectionData) => {
    try {
      localStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({ __version: STORAGE_VERSION, data: d })
      );
    } catch {
      // ignore
    }
  };

  const saveQuoteSection = useCallback((d: IQuoteSectionData) => {
    setDataState(d);
    persist(d);
  }, []);

  const setShowOnHomepage = useCallback((value: boolean) => {
    setDataState((prev) => {
      const next = { ...prev, showOnHomepage: value };
      persist(next);
      return next;
    });
  }, []);

  return {
    quoteSection: data,
    saveQuoteSection,
    setShowOnHomepage,
  };
}
