import { useState, useMemo, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useSeo } from '@/hooks/useSeo';
import { motion } from 'framer-motion';
import {
  ChevronLeft,
  ChevronRight,
  ArrowLeft,
  ArrowRight,
  CheckCircle2,
  MessageCircle,
  Package,
  ShieldCheck,
  Zap,
  Globe,
  ImageOff,
  HelpCircle,
  FileText,
  Star,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Image } from '@/components/ui/image';
import { useProducts } from '@/hooks/useProducts';
import { useI18n } from '@/i18n/I18nContext';
import { getI18nValue } from '@/lib/i18n-text';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { useFooterSettings } from '@/hooks/useFooterSettings';
import { normalizeWhatsAppUrl } from '@/lib/whatsapp';
import { toast } from 'sonner';

export default function ProductDetailPage() {
  const { t, language } = useI18n();
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { products } = useProducts({ preferRemote: true });

  const { settings: footerSettings } = useFooterSettings({ preferRemote: true });

  const product = useMemo(
    () => products.find((p) => p.id === id || p.slug === id),
    [products, id]
  );

  const productName = useMemo(
    () => (product ? getI18nValue(product.name, language) : ''),
    [product, language]
  );
  const productDesc = useMemo(
    () => (product ? getI18nValue(product.description, language) : ''),
    [product, language]
  );

  const seoDescription = useMemo(() => {
    if (!product) return t('seo.productDetailDescription');
    const getField = (key: string) => {
      const f = (product.customFields || []).find((cf) => {
        const k = typeof cf.key === 'string' ? cf.key : cf.key[language] ?? cf.key.en ?? '';
        return k.toLowerCase() === key.toLowerCase();
      });
      if (!f) return '';
      return typeof f.value === 'string' ? f.value : f.value[language] ?? f.value.en ?? '';
    };
    const specStr = [
      getField('Power') && `Power: ${getField('Power')}`,
      getField('IP Rating') && `IP Rating: ${getField('IP Rating')}`,
      getField('Material') && `Material: ${getField('Material')}`,
    ].filter(Boolean).join(', ');
    return `${productName}. ${specStr}. ${t('seo.productDetailDescription')}`.slice(0, 160);
  }, [product, productName, language, t]);

  const [activeImageIndex, setActiveImageIndex] = useState(0);
  const [imgErrors, setImgErrors] = useState<Record<number, boolean>>({});

  const images = useMemo(() => {
    if (!product) return [];
    if (product.gallery && product.gallery.length > 0) {
      return product.gallery.filter((g) => g && g.length > 0);
    }
    if (product.image) return [product.image];
    return [];
  }, [product]);

  const hasImages = images.length > 0;

  const relatedProducts = useMemo(() => {
    if (!product || !product.relatedProducts || product.relatedProducts.length === 0) return [];
    return product.relatedProducts
      .map((slug) => products.find((p) => p.slug === slug || p.id === slug))
      .filter((p): p is NonNullable<typeof p> => !!p && p.id !== product.id)
      .slice(0, 3);
  }, [product, products]);

  useEffect(() => {
    setActiveImageIndex(0);
    setImgErrors({});
  }, [id]);

  // Product + BreadcrumbList schema
  const productSchema = useMemo(() => {
    if (!product) return undefined;
    return [
      {
        '@context': 'https://schema.org',
        '@type': 'Product',
        name: productName,
        image: images.length > 0 ? images : [product.image],
        description: productDesc,
        brand: { '@type': 'Brand', name: 'OWELL Industrial' },
        manufacturer: { '@type': 'Organization', name: 'OWELL Industrial' },
        sku: product.id,
        mpn: product.id,
        offers: {
          '@type': 'Offer',
          availability: 'https://schema.org/InStock',
          url: typeof window !== 'undefined' ? window.location.href : '',
          priceCurrency: 'USD',
          itemCondition: 'https://schema.org/NewCondition',
        },
        aggregateRating: {
          '@type': 'AggregateRating',
          ratingValue: '4.9',
          reviewCount: '128',
        },
      },
      {
        '@context': 'https://schema.org',
        '@type': 'BreadcrumbList',
        itemListElement: [
          {
            '@type': 'ListItem',
            position: 1,
            name: 'Home',
            item: typeof window !== 'undefined' ? `${window.location.origin}/` : '/',
          },
          {
            '@type': 'ListItem',
            position: 2,
            name: 'Products',
            item: typeof window !== 'undefined' ? `${window.location.origin}/products` : '/products',
          },
          {
            '@type': 'ListItem',
            position: 3,
            name: productName,
          },
        ],
      },
    ];
  }, [product, productName, productDesc, images]);

  useSeo({
    title: productName ? `${productName} - LED Sensor Light | OWELL Industrial` : t('seo.productDetailTitle'),
    description: seoDescription,
    keywords: `${productName}, LED sensor light, PIR motion sensor light, motion sensor LED, ${t('seo.productDetailKeywords')}`,
    image: product?.image,
    type: 'product',
    pageKey: 'product-detail',
    schema: productSchema,
  });

  const handlePrev = () => {
    if (!hasImages) return;
    setActiveImageIndex((prev) => (prev <= 0 ? images.length - 1 : prev - 1));
  };

  const handleNext = () => {
    if (!hasImages) return;
    setActiveImageIndex((prev) => (prev >= images.length - 1 ? 0 : prev + 1));
  };

  const handleInquiry = () => {
    if (product) {
      navigate(`/contact?product=${encodeURIComponent(product.id)}`);
    }
  };

  const handleWhatsApp = () => {
    if (product) {
      const msg = `Hi, I'm interested in ${productName}. Could you send me more details and a quotation?`;
      const url = normalizeWhatsAppUrl(footerSettings.whatsappUrl, msg);
      if (url) {
        window.open(url, '_blank');
      }
    }
  };

  if (!product) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="text-center space-y-4">
          <Package className="size-16 mx-auto text-muted-foreground/50" />
          <h2 className="text-xl font-semibold text-foreground">
            {t('productDetail.notFound')}
          </h2>
          <Button variant="outline" onClick={() => navigate('/products')}>
            <ArrowLeft className="size-4 mr-2" />
            {t('productDetail.backToList')}
          </Button>
        </div>
      </div>
    );
  }

  const allFields = product.customFields;

  return (
    <div className="min-h-screen bg-background">
      {/* Breadcrumb */}
      <div className="border-b border-border bg-card/30">
        <div className="max-w-7xl mx-auto px-4 md:px-6 py-4">
          <PageBreadcrumb
            firstItem={{ label: t('nav.home'), href: '/', icon: 'home' }}
            items={[
              { label: t('nav.products'), href: '/products' },
              { label: productName },
            ]}
          />
        </div>
      </div>

      {/* ========== Main Product Section ========== */}
      <section className="w-full py-8 md:py-12">
        <div className="max-w-7xl mx-auto px-4 md:px-6">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 md:gap-12">
            {/* ===== Left: Image Gallery ===== */}
            <motion.div
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.5 }}
            >
              {/* Main Image */}
              <div className="relative aspect-square overflow-hidden group">
                {hasImages && !imgErrors[activeImageIndex] ? (
                  <Image
                    src={images[activeImageIndex]}
                    alt={`${productName} - view ${activeImageIndex + 1}`}
                    className="w-full h-full object-contain"
                    onError={() =>
                      setImgErrors((prev) => ({ ...prev, [activeImageIndex]: true }))
                    }
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center">
                    <div className="text-center text-muted-foreground">
                      <ImageOff className="size-12 mx-auto mb-2 opacity-50" />
                      <p className="text-sm">
                        {t('productDetail.noImage')}
                      </p>
                    </div>
                  </div>
                )}

                {/* Arrow buttons */}
                {hasImages && images.length > 1 && (
                  <>
                    <button
                      onClick={handlePrev}
                      className="absolute left-3 top-1/2 -translate-y-1/2 size-10 rounded-full bg-background/90 backdrop-blur border border-border flex items-center justify-center text-foreground hover:bg-primary hover:text-primary-foreground transition-colors z-10 md:opacity-0 md:group-hover:opacity-100"
                      aria-label="Previous image"
                    >
                      <ChevronLeft className="size-5" />
                    </button>
                    <button
                      onClick={handleNext}
                      className="absolute right-3 top-1/2 -translate-y-1/2 size-10 rounded-full bg-background/90 backdrop-blur border border-border flex items-center justify-center text-foreground hover:bg-primary hover:text-primary-foreground transition-colors z-10 md:opacity-0 md:group-hover:opacity-100"
                      aria-label="Next image"
                    >
                      <ChevronRight className="size-5" />
                    </button>
                  </>
                )}

                {/* Dot indicators */}
                {hasImages && images.length > 1 && (
                  <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-2">
                    {images.map((_, i) => (
                      <button
                        key={i}
                        onClick={() => setActiveImageIndex(i)}
                        className={`size-2 rounded-full transition-colors ${
                          i === activeImageIndex
                            ? 'bg-primary w-6'
                            : 'bg-foreground/30 hover:bg-foreground/50'
                        }`}
                        aria-label={`Go to image ${i + 1}`}
                      />
                    ))}
                  </div>
                )}
              </div>

              {/* Thumbnails */}
              {hasImages && images.length > 1 && (
                <div className="mt-4 flex gap-2 overflow-x-auto pb-2">
                  {images.map((img, i) => (
                    <button
                      key={i}
                      onClick={() => setActiveImageIndex(i)}
                      className={`shrink-0 w-20 h-20 border rounded-sm overflow-hidden transition-colors ${
                        i === activeImageIndex
                          ? 'border-primary ring-2 ring-primary/30'
                          : 'border-border hover:border-muted-foreground'
                      }`}
                    >
                      {!imgErrors[i + 100] ? (
                        <Image
                          src={img}
                          alt={`Thumbnail ${i + 1}`}
                          className="w-full h-full object-contain p-1 bg-background"
                          onError={() =>
                            setImgErrors((prev) => ({ ...prev, [i + 100]: true }))
                          }
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center bg-background">
                          <ImageOff className="size-5 text-muted-foreground/50" />
                        </div>
                      )}
                      {i === 0 && (
                        <div className="absolute -mt-5 ml-1">
                          <Badge className="bg-primary text-[10px] px-1.5 py-0">
                            Main
                          </Badge>
                        </div>
                      )}
                    </button>
                  ))}
                  {images.length < 6 &&
                    Array.from({ length: 6 - images.length }).map((_, i) => (
                      <div
                        key={`empty-${i}`}
                        className="shrink-0 w-20 h-20 border border-dashed border-border/50 rounded-sm bg-background/50"
                      />
                    ))}
                </div>
              )}
            </motion.div>

            {/* ===== Right: Product Info ===== */}
            <motion.div
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.5, delay: 0.1 }}
              className="flex flex-col"
            >
              <h1 className="text-2xl md:text-3xl font-bold text-foreground mb-4 tracking-tight">
                {productName}
              </h1>

              {/* Feature Badges */}
              {product.features && product.features.length > 0 && (
                <div className="flex flex-wrap gap-2 mb-5">
                  {(product.features || []).slice(0, 6).map((feat, i) => (
                    <Badge
                      key={i}
                      variant="outline"
                      className="border-border/70 text-muted-foreground bg-card/50"
                    >
                      <CheckCircle2 className="size-3 mr-1 text-primary" />
                      {getI18nValue(feat, language)}
                    </Badge>
                  ))}
                </div>
              )}

              <p className="text-muted-foreground leading-relaxed mb-6">
                {productDesc}
              </p>

              {/* Specs Section - Modern Soft Style */}
              {allFields.length > 0 && (
                <div className="mb-6">
                  {/* Section Header */}
                  <div className="mb-5">
                    <div className="flex items-center gap-2.5 mb-2">
                      <div className="w-8 h-[3px] rounded-full bg-gradient-to-r from-primary to-primary/30" />
                      <h3 className="text-lg font-semibold text-foreground">
                        {t('productDetail.specs')}
                      </h3>
                    </div>
                    <p className="text-sm text-muted-foreground ml-10.5">
                      {t('productDetail.specsHint')}
                    </p>
                  </div>

                  {/* Spec Cards - Soft info grid */}
                  <div className="grid grid-cols-2 gap-3">
                    {allFields.map((f, i) => (
                      <div
                        key={i}
                        className="group bg-card/40 hover:bg-card/70 transition-all duration-200 rounded-lg p-3.5 border border-border/40 hover:border-border/80"
                      >
                        <div className="text-xs text-muted-foreground mb-1">
                          {getI18nValue(f.key, language)}
                        </div>
                        <div className="text-sm font-medium text-foreground">
                          {getI18nValue(f.value, language)}
                        </div>
                      </div>
                    ))}
                  </div>

                  {/* Bottom hint */}
                  <div className="mt-3 flex items-center justify-center gap-2">
                    <div className="size-1 rounded-full bg-primary/40" />
                    <span className="text-xs text-muted-foreground/70">
                       {t('productDetail.specsCount').replace('{n}', String(allFields.length))}
                    </span>
                    <div className="size-1 rounded-full bg-primary/40" />
                  </div>
                </div>
              )}

              {/* CTA Buttons */}
              <div className="flex flex-col sm:flex-row gap-3 mt-auto pt-2">
                <Button
                  className="flex-1 bg-primary hover:bg-primary/90 text-primary-foreground h-11"
                  onClick={handleInquiry}
                >
                  <ShieldCheck className="size-4 mr-2" />
                  {t('productDetail.getQuotation')}
                </Button>
                <Button
                  variant="outline"
                  className="flex-1 h-11 border-green-600/50 text-green-400 hover:bg-green-600/10 hover:text-green-300 hover:border-green-500"
                  onClick={handleWhatsApp}
                >
                  <MessageCircle className="size-4 mr-2" />
                  WhatsApp
                </Button>
              </div>
            </motion.div>
          </div>
        </div>
      </section>

      {/* ========== Rich Product Description ========== */}
      {product.showRichDescription !== false &&
        product.richDescription &&
        getI18nValue(product.richDescription, language) && (
          <section className="w-full py-10 md:py-14 border-t border-border bg-muted/10">
            <div className="max-w-4xl mx-auto px-4 md:px-6">
              <div className="text-center mb-8">
                <h2 className="text-2xl md:text-3xl font-bold text-foreground mb-2">
                  {t('productDetail.productDescription')}
                </h2>
              </div>
              <div
                className="prose prose-sm dark:prose-invert max-w-none text-foreground leading-relaxed prose-headings:font-semibold prose-a:text-primary prose-headings:text-foreground prose-p:text-muted-foreground prose-strong:text-foreground prose-li:text-muted-foreground prose-img:rounded-sm prose-img:border prose-img:border-border/50"
                dangerouslySetInnerHTML={{
                  __html: getI18nValue(product.richDescription, language),
                }}
              />
            </div>
          </section>
        )}

      {/* ========== Product Gallery (Large Views) ========== */}
      {images.length > 1 && (
        <section className="w-full py-10 md:py-14 border-t border-border bg-muted/20">
          <div className="max-w-7xl mx-auto px-4 md:px-6">
            <div className="text-center mb-8 md:mb-10">
              <h2 className="text-2xl md:text-3xl font-bold text-foreground mb-2">
                {t('productDetail.gallery')}
              </h2>
            </div>

            <div className="grid grid-cols-1 gap-8 max-w-4xl mx-auto">
              {images.slice(1).map((img, i) => {
                const realIndex = i + 1;
                const isError = imgErrors[realIndex + 200];
                return (
                  <div key={realIndex} className="group">
                    <div className="relative aspect-square overflow-hidden">
                      {!isError ? (
                        <Image
                          src={img}
                          alt={`${productName} - view ${realIndex + 1}`}
                          className="w-full h-full object-contain transition-transform duration-700 group-hover:scale-105"
                          onError={() =>
                            setImgErrors((prev) => ({ ...prev, [realIndex + 200]: true }))
                          }
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center">
                          <ImageOff className="size-10 text-muted-foreground/50" />
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </section>
      )}

      {/* ========== Application Scenarios ========== */}
      {product.applicationScenes && product.applicationScenes.length > 0 && (
        <section className="w-full py-10 md:py-14 border-t border-border">
          <div className="max-w-7xl mx-auto px-4 md:px-6">
            <div className="text-center mb-10">
              <Badge
                variant="outline"
                className="border-primary/40 text-primary bg-primary/5 mb-3"
              >
                 <Globe className="size-3 mr-1" />
                 {t('productDetail.applicationsBadge') || 'Applications'}
               </Badge>
              <h2 className="text-2xl md:text-3xl font-bold text-foreground mb-2">
                {t('productDetail.applications') || 'Application Scenarios'}
              </h2>
              <p className="text-muted-foreground max-w-xl mx-auto">
                {t('productDetail.applicationsDesc') ||
                  'Versatile design suitable for various indoor and outdoor environments.'}
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
              {(product.applicationScenes || []).map((scene, i) => (
                <motion.div
                  key={i}
                  initial={{ opacity: 0, y: 16 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.4, delay: i * 0.05 }}
                  className="p-5 bg-card border border-border rounded-sm hover:border-primary/40 transition-colors group"
                >
                  <div className="size-10 rounded-sm bg-primary/10 flex items-center justify-center mb-3 group-hover:bg-primary/20 transition-colors">
                    <CheckCircle2 className="size-5 text-primary" />
                  </div>
                  <h3 className="font-semibold text-foreground mb-1.5">
                    {getI18nValue(scene.title, language)}
                  </h3>
                  <p className="text-sm text-muted-foreground leading-relaxed">
                    {getI18nValue(scene.description, language)}
                  </p>
                </motion.div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* ========== Long Description ========== */}
      {product.longDescription && getI18nValue(product.longDescription, language).trim() && (
        <section className="w-full py-10 md:py-14 border-t border-border bg-muted/10">
          <div className="max-w-4xl mx-auto px-4 md:px-6">
            <div className="text-center mb-8">
              <Badge
                variant="outline"
                className="border-primary/40 text-primary bg-primary/5 mb-3"
              >
                <FileText className="size-3 mr-1" />
                Detail
              </Badge>
              <h2 className="text-2xl md:text-3xl font-bold text-foreground mb-2">
                {t('productDetail.productDescription') || 'Product Description'}
              </h2>
            </div>
            <div className="prose prose-sm dark:prose-invert max-w-none prose-headings:text-foreground prose-headings:font-semibold prose-p:text-muted-foreground prose-strong:text-foreground prose-li:text-muted-foreground prose-a:text-primary">
              <p className="text-muted-foreground leading-relaxed whitespace-pre-line">
                {getI18nValue(product.longDescription, language)}
              </p>
            </div>
          </div>
        </section>
      )}

      {/* ========== Product FAQs ========== */}
      {product.productFaqs && product.productFaqs.length > 0 && (
        <section className="w-full py-10 md:py-14 border-t border-border">
          <div className="max-w-4xl mx-auto px-4 md:px-6">
            <div className="text-center mb-8">
              <Badge
                variant="outline"
                className="border-primary/40 text-primary bg-primary/5 mb-3"
              >
                <HelpCircle className="size-3 mr-1" />
                FAQ
              </Badge>
              <h2 className="text-2xl md:text-3xl font-bold text-foreground mb-2">
                {t('productDetail.faq') || 'Frequently Asked Questions'}
              </h2>
              <p className="text-muted-foreground max-w-xl mx-auto">
                Common questions about this product and our service.
              </p>
            </div>

            <div className="space-y-3">
              {(product.productFaqs || []).map((faq, i) => (
                <motion.div
                  key={i}
                  initial={{ opacity: 0, y: 12 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.3, delay: i * 0.04 }}
                  className="border border-border rounded-sm bg-card overflow-hidden"
                >
                  <div className="px-5 py-4 flex items-start gap-3 border-b border-border/50">
                    <div className="size-6 shrink-0 rounded-sm bg-primary/10 flex items-center justify-center mt-0.5">
                      <span className="text-xs font-bold text-primary">Q</span>
                    </div>
                    <h3 className="font-semibold text-foreground text-base flex-1">
                      {getI18nValue(faq.question, language)}
                    </h3>
                  </div>
                  <div className="px-5 py-4 flex items-start gap-3">
                    <div className="size-6 shrink-0 rounded-sm bg-muted flex items-center justify-center mt-0.5">
                      <span className="text-xs font-bold text-muted-foreground">A</span>
                    </div>
                    <p className="text-sm text-muted-foreground leading-relaxed flex-1">
                      {getI18nValue(faq.answer, language)}
                    </p>
                  </div>
                </motion.div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* ========== Related Products ========== */}
      {relatedProducts.length > 0 && (
        <section className="w-full py-10 md:py-14 border-t border-border bg-muted/10">
          <div className="max-w-7xl mx-auto px-4 md:px-6">
            <div className="flex items-end justify-between mb-8">
              <div>
                <Badge
                  variant="outline"
                  className="border-primary/40 text-primary bg-primary/5 mb-3"
                >
                  <Star className="size-3 mr-1" />
                  Related
                </Badge>
                <h2 className="text-2xl md:text-3xl font-bold text-foreground">
                  {t('productDetail.relatedProducts') || 'Related Products'}
                </h2>
              </div>
              <Button
                variant="outline"
                size="sm"
                onClick={() => navigate('/products')}
                className="hidden md:inline-flex"
              >
                View All
                <ArrowRight className="size-4 ml-1" />
              </Button>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
              {relatedProducts.map((rp, i) => (
                <motion.div
                  key={rp.id}
                  initial={{ opacity: 0, y: 16 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.4, delay: i * 0.08 }}
                  whileHover={{ y: -3 }}
                  className="bg-card border border-border rounded-sm overflow-hidden cursor-pointer group"
                  onClick={() => navigate(`/products/${rp.id}`)}
                >
                  <div className="aspect-square bg-muted/30 relative overflow-hidden">
                    <Image
                      src={rp.image}
                      alt={getI18nValue(rp.name, language)}
                      className="w-full h-full object-contain p-4 transition-transform duration-500 group-hover:scale-105"
                      onError={(e) => {
                        const target = e.target as HTMLImageElement;
                        target.style.display = 'none';
                      }}
                    />
                  </div>
                  <div className="p-4">
                    <h3 className="font-semibold text-foreground text-sm mb-2 line-clamp-2 min-h-[2.5rem]">
                      {getI18nValue(rp.name, language)}
                    </h3>
                    <div className="flex items-center justify-between">
                      <span className="text-xs text-muted-foreground">{rp.category}</span>
                      <span className="text-primary text-xs font-medium flex items-center gap-1 group-hover:gap-2 transition-all">
                        View <ArrowRight className="size-3" />
                      </span>
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Back to products */}
      <section className="w-full py-8 border-t border-border">
        <div className="max-w-7xl mx-auto px-4 md:px-6">
          <Button variant="outline" onClick={() => navigate('/products')}>
            <ArrowLeft className="size-4 mr-2" />
            {t('productDetail.backToList')}
          </Button>
        </div>
      </section>
    </div>
  );
}
