import * as React from 'react';
import { cn } from '@/lib/utils';
import { imgPath } from '@/utils/img-path';
type ImageFormat = 'jpg' | 'png' | 'webp' | 'bmp' | 'gif' | 'tiff';

type NativeImgProps = React.ComponentPropsWithoutRef<'img'>;

export interface ImageProps extends NativeImgProps {
  quality?: number;
  format?: ImageFormat;
  breakpoints?: Array<number>;
}

const DEFAULT_QUALITY = 80;
const DEFAULT_RESOLUTIONS: number[] = [
  16, 32, 48, 64, 96, 128, 256, 384, 640, 750, 828, 1080, 1200, 1920, 2048,
  3840,
];

const SRC_ALLOWLIST = [
  '/runtime/api/v1/storage/object/',
  '/aily/api/v1/feisuda/attachments/',
  '/aily/api/v1/files/static/',
  // 注意：/spark/app/ 不在白名单中
  // 妙搭平台 storage 静态资源走原生 img 路径，避免 x-tos-process 参数导致加载失败
];

// 图片加载失败时的占位图（内联 SVG，工业风深灰背景 + 灯具图标）
const PLACEHOLDER_DATA_URL =
  'data:image/svg+xml;utf8,' +
  encodeURIComponent(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 300">` +
      `<rect width="400" height="300" fill="#1a1a1a"/>` +
      `<path d="M200 80 L200 140 M170 110 L230 110 M160 150 L240 150" stroke="#e63946" stroke-width="3" stroke-linecap="round" fill="none"/>` +
      `<rect x="170" y="150" width="60" height="60" rx="4" stroke="#444" stroke-width="2" fill="none"/>` +
      `<text x="200" y="240" text-anchor="middle" fill="#666" font-family="sans-serif" font-size="14">Image unavailable</text>` +
    `</svg>`
  );

// 模块级缓存 webp 检测结果，只检测一次
let webpSupported: boolean | null = null;

function getClosestResolution(target: number): number {
  return DEFAULT_RESOLUTIONS.reduce((prev, curr) => {
    return Math.abs(curr - target) < Math.abs(prev - target) ? curr : prev;
  });
}

function applyParamsToUrl(
  src: string,
  params: Record<string, string | number | undefined>,
): string {
  const search = Object.entries(params)
    .filter(([, v]) => v !== undefined && v !== null && v !== '')
    .map(([k, v]) => {
      return `${k},${v}`;
    })
    .join('/');
  if (!search) return src;

  const [pathAndQuery = '', hash] = src.split('#');
  const [base, query] = pathAndQuery.split('?');
  const urlParams = new URLSearchParams(query);
  urlParams.set('x-tos-process', `image/${search}`);

  return `${base}?${urlParams.toString()}${hash ? '#' + hash : ''}`;
}

function isTargetSrc(originSrc: string) {
  return SRC_ALLOWLIST.some((item) => originSrc.includes(item));
}

function supportWebp() {
  if (webpSupported !== null) return webpSupported;
  try {
    webpSupported =
      document
        .createElement('canvas')
        .toDataURL('image/webp')
        .indexOf('data:image/webp') === 0;
  } catch (err) {
    webpSupported = false;
  }
  return webpSupported;
}

function buildSrcSet(
  src: string,
  widths: number[],
  format: ImageFormat | undefined,
  quality: number,
  width?: number,
  sizes?: string,
): string | undefined {
  if (!widths || widths.length === 0 || (!width && !sizes)) return undefined;
  const fmt = format;
  if (width) {
    return [1, 2]
      .map((dpr) => {
        const targetWidth = getClosestResolution(width * dpr);
        return `${applyParamsToUrl(src, { resize: `w_${targetWidth}`, quality: `Q_${quality}`, format: fmt })} ${dpr}x`;
      })
      .join(', ');
  }
  return widths
    .map(
      (w) =>
        `${applyParamsToUrl(src, { resize: `w_${w}`, quality: `Q_${quality}`, format: fmt })} ${w}w`,
    )
    .join(', ');
}

/**
 * 判断是否为 data URL / blob URL（base64 内联图）
 * 这类图片不需要回退逻辑，失败直接用占位图
 */
function isInlineSrc(src: string): boolean {
  return src.startsWith('data:') || src.startsWith('blob:');
}

// ===================== 子组件 1：非白名单路径（本地路径 / base64 / 外链等）=====================

interface ImageNativeProps extends NativeImgProps {
  resolvedSrc: string | undefined;
}

const ImageNative = React.forwardRef<HTMLImageElement, ImageNativeProps>(
  function ImageNative(
    { resolvedSrc, width, height, sizes, srcSet: userSrcSet, className, loading = 'lazy', decoding = 'async', ...rest },
    ref,
  ) {
  const [imgSrc, setImgSrc] = React.useState<string | undefined>(resolvedSrc);
  // 错误重试阶段：0=初始（basename 绝对路径）→ 1=相对路径回退 → 2=占位图
  const [errorStage, setErrorStage] = React.useState(0);

  // 生成相对路径 fallback（./images/xxx.jpg）
  // 用于 basename 探测失败场景下的二级回退
  // data URL / blob URL 不需要相对路径回退
  const relativeFallback = React.useMemo(() => {
    if (!resolvedSrc) return '';
    if (isInlineSrc(resolvedSrc)) return resolvedSrc; // inline 图回退等于自身，实际不会走到 stage 1
    const imagesIdx = resolvedSrc.indexOf('/images/');
    if (imagesIdx >= 0) {
      return '.' + resolvedSrc.slice(imagesIdx);
    }
    return resolvedSrc;
  }, [resolvedSrc]);

  // src 变化时重置错误状态
  React.useEffect(() => {
    setErrorStage(0);
    setImgSrc(resolvedSrc);
  }, [resolvedSrc]);

  const handleError = React.useCallback((e: React.SyntheticEvent<HTMLImageElement>) => {
    setErrorStage((prev) => {
      if (prev === 0) {
        // inline 图（base64/blob）失败直接跳占位图，不需要相对路径回退
        if (resolvedSrc && isInlineSrc(resolvedSrc)) {
          setImgSrc(PLACEHOLDER_DATA_URL);
          if (rest.onError) rest.onError(e);
          return 2;
        }
        // 第一级失败：尝试相对路径 fallback
        setImgSrc(relativeFallback);
        return 1;
      }
      if (prev === 1) {
        // 第二级失败：显示占位图
        setImgSrc(PLACEHOLDER_DATA_URL);
        if (rest.onError) rest.onError(e);
        return 2;
      }
      return prev;
    });
  }, [relativeFallback, resolvedSrc, rest.onError]);

  // src 为空/无效时直接显示占位图
  if (!resolvedSrc) {
    return (
      <img
        {...rest}
        ref={ref}
        src={PLACEHOLDER_DATA_URL}
        width={width}
        height={height}
        sizes={sizes}
        srcSet={userSrcSet}
        className={cn('object-contain bg-muted', className)}
        loading={loading}
        decoding={decoding}
      />
    );
  }

  return (
    <img
      {...rest}
      ref={ref}
      src={imgSrc}
      width={width}
      height={height}
      sizes={sizes}
      srcSet={userSrcSet}
      className={cn(
        errorStage >= 2 ? 'object-contain bg-muted' : '',
        className,
      )}
      loading={loading}
      decoding={decoding}
      onError={handleError}
    />
  );
});

ImageNative.displayName = 'ImageNative';

// ===================== 子组件 2：白名单路径（妙搭 storage 等支持图片处理的 CDN）=====================

interface ImageTargetProps extends NativeImgProps {
  src: string;
  quality: number;
  format?: ImageFormat;
  breakpoints: number[];
  defaultFormat: ImageFormat | undefined;
}

const ImageTarget = React.forwardRef<HTMLImageElement, ImageTargetProps>(
  function ImageTarget(
    { src, quality, format, breakpoints, defaultFormat, width, height, sizes, srcSet: userSrcSet, className, loading = 'lazy', decoding = 'async', ...rest },
    ref,
  ) {
  const numericWidth = typeof width === 'number' ? width : undefined;

  const srcSet = React.useMemo(
    () =>
      userSrcSet ??
      buildSrcSet(
        src,
        breakpoints,
        format ?? (defaultFormat as ImageFormat),
        quality,
        numericWidth,
        sizes,
      ),
    [src, userSrcSet, breakpoints, format, defaultFormat, quality, numericWidth, sizes],
  );

  const baseSrc = React.useMemo(
    () =>
      applyParamsToUrl(src, {
        resize: numericWidth ? `w_${numericWidth}` : undefined,
        quality: `Q_${quality}`,
        format: format ?? defaultFormat,
      }),
    [src, quality, format, defaultFormat, numericWidth],
  );

  const [imgSrc, setImgSrc] = React.useState<string>(baseSrc);
  const [hasError, setHasError] = React.useState(false);

  React.useEffect(() => {
    setHasError(false);
    setImgSrc(baseSrc);
  }, [baseSrc]);

  const handleError = React.useCallback((e: React.SyntheticEvent<HTMLImageElement>) => {
    setHasError(true);
    setImgSrc(PLACEHOLDER_DATA_URL);
    if (rest.onError) rest.onError(e);
  }, [rest.onError]);

  return (
    <img
      {...rest}
      ref={ref}
      src={imgSrc}
      width={width}
      height={height}
      sizes={sizes}
      srcSet={srcSet}
      className={cn(
        'bg-linear-to-b from-gray-50/20 to-gray-200/20',
        hasError ? 'object-contain' : '',
        className,
      )}
      loading={loading}
      decoding={decoding}
      onError={handleError}
    />
  );
});

ImageTarget.displayName = 'ImageTarget';

// ===================== 顶层组件：根据 src 类型选择子组件 =====================
// ⚠️ 顶层组件不能有 hooks 在条件分支之后，也不能在分支数量不同
// 采用 key 驱动的子组件切换：当 src 从白名单切换到非白名单时，
// 子组件实例会被销毁并重建（各自独立的 hooks 树），从根本上避免 hooks 数量不匹配问题

export const Image = React.forwardRef<HTMLImageElement, ImageProps>(
  (
    {
      src,
      width,
      height,
      quality = DEFAULT_QUALITY,
      format,
      sizes,
      srcSet: userSrcSet,
      breakpoints = DEFAULT_RESOLUTIONS,
      className,
      loading = 'lazy',
      decoding = 'async',
      ...rest
    },
    ref,
  ) => {
    // 顶层唯一 hook：webp 格式检测（模块级缓存，每个实例第一次挂载时读一次）
    const defaultFormat = React.useMemo(
      () => (supportWebp() ? 'webp' : undefined) as ImageFormat | undefined,
      [],
    );

    const isStringSrc = typeof src === 'string';
    const target = isStringSrc && isTargetSrc(src);

    // 白名单路径 → ImageTarget（支持 CDN 图片处理 + srcSet 优化）
    if (target) {
      return (
        <ImageTarget
          {...rest}
          ref={ref}
          src={src as string}
          quality={quality}
          format={format}
          breakpoints={breakpoints}
          defaultFormat={defaultFormat}
          width={width}
          height={height}
          sizes={sizes}
          srcSet={userSrcSet}
          className={className}
          loading={loading}
          decoding={decoding}
        />
      );
    }

    // 非白名单路径 → ImageNative（原生 img + 两级回退 + 占位图）
    const resolvedSrc = isStringSrc && (src as string).trim()
      ? imgPath(src as string)
      : undefined;

    return (
      <ImageNative
        {...rest}
        ref={ref}
        resolvedSrc={resolvedSrc}
        width={width}
        height={height}
        sizes={sizes}
        srcSet={userSrcSet}
        className={className}
        loading={loading}
        decoding={decoding}
      />
    );
  },
);

Image.displayName = 'Image';

export default Image;
