/**
 * 本地访问统计 Hook（简易版）
 *
 * 功能：
 * - 记录每次页面浏览的路径和时间戳
 * - 统计总 PV、今日 PV、热门页面 Top5、最近访问时间
 * - 数据保存在 localStorage，最多保留最近 1000 条
 *
 * 注意：这是本地统计，同一浏览器的数据有限，
 *       仅用作后台仪表盘的大致参考，正式统计请配置 Google Analytics。
 */

import { useCallback, useEffect, useMemo, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { logger } from '@lark-apaas/client-toolkit-lite';

const STORAGE_KEY = '__app_ledlight_analytics_pageviews';
const MAX_RECORDS = 1000;

export interface PageViewRecord {
  path: string;
  ts: number; // timestamp ms
}

function loadRecords(): PageViewRecord[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) return parsed;
  } catch (e) {
    logger.warn('[Analytics] Failed to load page views: ' + String(e));
  }
  return [];
}

function saveRecords(list: PageViewRecord[]) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(list));
  } catch (e) {
    logger.warn('[Analytics] Failed to save page views: ' + String(e));
  }
}

function getDateKey(ts: number): string {
  const d = new Date(ts);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

// 排除后台管理路径，不记入前台流量
function shouldTrack(path: string): boolean {
  if (path.startsWith('/admin')) return false;
  if (path.startsWith('/__')) return false;
  return true;
}

// 独立函数：记录一次页面访问（可在 hook 外调用）
export function trackPageView(path: string) {
  if (!shouldTrack(path)) return;
  try {
    const list = loadRecords();
    const record: PageViewRecord = { path, ts: Date.now() };
    list.push(record);
    // 超过上限则丢弃最老的
    if (list.length > MAX_RECORDS) {
      list.splice(0, list.length - MAX_RECORDS);
    }
    saveRecords(list);
  } catch (e) {
    logger.warn('[Analytics] trackPageView error: ' + String(e));
  }
}

export interface AnalyticsStats {
  totalPV: number;
  todayPV: number;
  lastVisitTime: number | null;
  lastVisitPage: string | null;
  topPages: { path: string; count: number }[];
  dailyTrend: { date: string; count: number }[]; // 最近 7 天
}

export function computeStats(records: PageViewRecord[]): AnalyticsStats {
  const totalPV = records.length;
  const todayKey = getDateKey(Date.now());
  const todayPV = records.filter((r) => getDateKey(r.ts) === todayKey).length;

  const sorted = [...records].sort((a, b) => b.ts - a.ts);
  const lastVisitTime = sorted[0]?.ts ?? null;
  const lastVisitPage = sorted[0]?.path ?? null;

  // Top 页面
  const pageMap: Record<string, number> = {};
  records.forEach((r) => {
    pageMap[r.path] = (pageMap[r.path] || 0) + 1;
  });
  const topPages = Object.entries(pageMap)
    .map(([path, count]) => ({ path, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 5);

  // 最近 7 天趋势
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const dailyTrend: { date: string; count: number }[] = [];
  for (let i = 6; i >= 0; i--) {
    const d = new Date(today);
    d.setDate(d.getDate() - i);
    const dateKey = getDateKey(d.getTime());
    const count = records.filter((r) => getDateKey(r.ts) === dateKey).length;
    dailyTrend.push({ date: dateKey, count });
  }

  return {
    totalPV,
    todayPV,
    lastVisitTime,
    lastVisitPage,
    topPages,
    dailyTrend,
  };
}

export function useAnalytics() {
  const [records, setRecords] = useState<PageViewRecord[]>(() => loadRecords());
  const location = useLocation();

  // 路由变化时记录一次页面访问
  useEffect(() => {
    const path = location.pathname;
    if (!shouldTrack(path)) return;
    trackPageView(path);
    setRecords(loadRecords());
  }, [location.pathname]);

  // 监听 storage 事件，跨 tab 同步
  useEffect(() => {
    const handleStorage = (e: StorageEvent) => {
      if (e.key && e.key.endsWith(STORAGE_KEY)) {
        setRecords(loadRecords());
      }
    };
    window.addEventListener('storage', handleStorage);
    return () => window.removeEventListener('storage', handleStorage);
  }, []);

  const stats = useMemo(() => computeStats(records), [records]);

  const refresh = useCallback(() => {
    setRecords(loadRecords());
  }, []);

  return {
    records,
    stats,
    refresh,
  };
}

/**
 * 非 hook 形式的统计获取（在 Context 或非 React 环境中使用）
 */
export function getAnalyticsStats(): AnalyticsStats {
  return computeStats(loadRecords());
}
