import { useEffect, useState, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Calendar, ArrowLeft, Share2, BookOpen } from 'lucide-react';
import { toast } from 'sonner';
import { useBlog } from '@/hooks/useBlog';
import { useI18n } from '@/i18n/I18nContext';
import { getI18nValue } from '@/lib/i18n-text';
import { imgPath, fixHtmlImagePaths } from '@/utils/img-path';
import { Button } from '@/components/ui/button';
import { Image } from '@/components/ui/image';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { useSeo } from '@/hooks/useSeo';
import { Badge } from '@/components/ui/badge';

export default function BlogDetailPage() {
  const { slug } = useParams();
  const navigate = useNavigate();
  const { t, language } = useI18n();
  const { articles, loading, getPublishedArticles, blogEnabled } = useBlog({ preferRemote: true });

  // Blog 版块关闭时重定向到首页
  useEffect(() => {
    if (!blogEnabled && !loading) {
      navigate('/', { replace: true });
    }
  }, [blogEnabled, loading, navigate]);

  const article = articles.find((a) => a.slug === slug) || null;
  const title = article ? getI18nValue(article.title, language) : '';
  const summary = article ? getI18nValue(article.summary, language) : '';
  const rawContent = article ? getI18nValue(article.content, language) : '';
  const content = useMemo(() => fixHtmlImagePaths(rawContent), [rawContent]);

  // SEO
  useSeo({
    title: title || t('blog.title'),
    description: summary || t('blog.subtitle'),
    type: 'article',
    image: article?.coverImage ? imgPath(article.coverImage) : undefined,
    pageKey: 'blog-detail',
  });

  // JSON-LD
  useEffect(() => {
    if (!article) return;
    const jsonLd = {
      '@context': 'https://schema.org',
      '@type': 'BlogPosting',
      headline: title,
      description: summary,
      image: article.coverImage ? [imgPath(article.coverImage)] : [],
      datePublished: article.publishDate,
      dateModified: article.publishDate,
      mainEntityOfPage: {
        '@type': 'WebPage',
        '@id': typeof window !== 'undefined' ? window.location.href : '',
      },
      author: {
        '@type': 'Organization',
        name: 'OWELL Industrial',
        url: typeof window !== 'undefined' ? `${window.location.origin}/` : '/',
      },
      publisher: {
        '@type': 'Organization',
        name: 'OWELL Industrial',
        logo: {
          '@type': 'ImageObject',
          url: typeof window !== 'undefined' ? `${window.location.origin}/logo.png` : '/logo.png',
        },
      },
    };

    const script = document.createElement('script');
    script.id = 'blog-article-jsonld';
    script.type = 'application/ld+json';
    script.text = JSON.stringify(jsonLd);
    document.head.appendChild(script);

    return () => {
      const el = document.getElementById('blog-article-jsonld');
      if (el) el.remove();
    };
  }, [article, title, summary]);

  if (!blogEnabled) {
    return null;
  }

  const handleShare = async () => {
    if (!article) return;
    const url = window.location.href;
    if (navigator.share) {
      try {
        await navigator.share({ title, url });
      } catch {
        // user cancelled
      }
    } else {
      try {
        await navigator.clipboard.writeText(url);
        toast.success(t('blog.shareLinkCopied'));
      } catch {
        toast.error(t('blog.linkCopyFailed'));
      }
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (!article) {
    return (
      <div className="min-h-screen bg-background">
        <div className="max-w-3xl mx-auto px-4 md:px-6 py-20 text-center">
          <h2 className="text-2xl font-semibold text-foreground mb-3">
            {t('blog.articleNotFound')}
          </h2>
          <p className="text-muted-foreground mb-6">
            {t('blog.articleNotFoundDesc')}
          </p>
          <Button onClick={() => navigate('/blog')} variant="outline">
            <ArrowLeft className="size-4 mr-2" />
            {t('blog.backToBlog')}
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      {/* Breadcrumb */}
      <div className="w-full border-b border-border bg-card/20">
        <div className="max-w-7xl mx-auto px-4 md:px-6 py-3">
          <PageBreadcrumb
            firstItem={{ label: t('nav.home'), href: '/', icon: 'home' }}
            items={[
              { label: t('nav.blog'), href: '/blog' },
              { label: title },
            ]}
          />
        </div>
      </div>

      {/* Article */}
      <article className="w-full">
        {/* Article Content */}
        <div className="max-w-3xl mx-auto px-4 md:px-6 py-10 md:py-14">
          {/* Hero Image */}
          {article.coverImage && (
            <div className="w-full aspect-[16/9] mb-8 overflow-hidden rounded-sm border border-border bg-muted">
              <Image
                src={imgPath(article.coverImage)}
                alt={title}
                className="w-full h-full object-cover"
              />
            </div>
          )}

          {/* Meta */}
          <div className="flex items-center gap-4 text-sm text-muted-foreground mb-5 flex-wrap">
            {article.category && (
              <Badge variant="outline" className="text-xs">
                <BookOpen className="size-3 mr-1" />
                {article.category}
              </Badge>
            )}
            <div className="flex items-center gap-1.5">
              <Calendar className="size-4" />
              <time dateTime={article.publishDate}>
                {new Date(article.publishDate).toLocaleDateString(undefined, {
                  year: 'numeric',
                  month: 'long',
                  day: 'numeric',
                })}
              </time>
            </div>
            <div className="ml-auto">
              <Button
                variant="outline"
                size="sm"
                onClick={handleShare}
                className="gap-1.5"
              >
                <Share2 className="size-3.5" />
                {t('blog.share')}
              </Button>
            </div>
          </div>

          {/* Title */}
          <h1 className="text-2xl md:text-3xl lg:text-4xl font-bold text-foreground leading-tight mb-6">
            {title}
          </h1>

          {/* Summary */}
          <p className="text-lg text-muted-foreground leading-relaxed mb-8 border-l-2 border-primary pl-4">
            {summary}
          </p>

          {/* Content */}
          {content ? (
            <div
              className="prose prose-sm md:prose-base max-w-none dark:prose-invert
                prose-headings:font-semibold
                prose-headings:text-foreground
                prose-p:text-foreground/90
                prose-p:leading-relaxed
                prose-a:text-primary
                prose-a:no-underline hover:prose-a:underline
                prose-strong:text-foreground
                prose-ul:text-foreground/90
                prose-ol:text-foreground/90
                prose-li:text-foreground/90
                prose-table:border-collapse
                prose-th:bg-card
                prose-th:border
                prose-th:border-border
                prose-th:px-4
                prose-th:py-2
                prose-td:border
                prose-td:border-border
                prose-td:px-4
                prose-td:py-2
                prose-img:rounded-sm
                prose-img:border
                prose-img:border-border
                prose-blockquote:border-l-primary
                 prose-blockquote:text-muted-foreground
                 prose-blockquote:bg-card/40
                 prose-blockquote:border
                 prose-blockquote:border-border
                 prose-blockquote:rounded-sm
                 prose-blockquote:py-4
                 prose-blockquote:px-5
                 prose-blockquote:my-6
                 prose-blockquote:not-italic
                 prose-blockquote:text-foreground/90
                prose-img:my-8
                 prose-img:shadow-lg
                 prose-img:border-primary/30
                prose-hr:border-border/60
               prose-h2:text-xl
               prose-h2:mt-8
               prose-h3:text-lg
               prose-h3:mt-6
               prose-code:text-primary
               prose-code:bg-primary/5
               prose-code:px-1.5
               prose-code:py-0.5
               prose-code:rounded-sm
               prose-code:before:content-none
               prose-code:after:content-none"
              dangerouslySetInnerHTML={{ __html: content }}
            />
          ) : (
            <div className="py-8 text-center text-muted-foreground">
              {t('blog.contentNotTranslated')}
            </div>
          )}

          {/* Back */}
          <div className="mt-12 pt-8 border-t border-border">
            <Button
              variant="outline"
              onClick={() => navigate('/blog')}
              className="gap-2"
            >
              <ArrowLeft className="size-4" />
              {t('blog.backToBlog')}
            </Button>
          </div>
        </div>
      </article>
    </div>
  );
}
