/**
 * 存储工具函数
 *
 * 提供 localStorage 用量统计、安全保存、缓存清理等通用能力。
 * 所有需要保存数据到 localStorage 的模块都应通过 safeSetItem 检查配额。
 *
 * 背景：浏览器 localStorage 通常只有 5MB 配额，当用户上传了很多 base64 图片
 * （站点图片、关于页画廊、Logo 等）后，可能导致其他配置（如统计设置）保存失败。
 */

import { logger } from '@lark-apaas/client-toolkit-lite';

const TOTAL_QUOTA_BYTES = 5 * 1024 * 1024; // 5MB

export interface StorageKeyInfo {
  key: string;
  size: number; // bytes
  sizeFormatted: string;
  percent: number; // 0-100, 占总配额比例
}

export interface StorageUsage {
  used: number; // bytes
  usedFormatted: string;
  total: number; // bytes
  totalFormatted: string;
  available: number; // bytes
  availableFormatted: string;
  percent: number; // 0-100
  keys: StorageKeyInfo[]; // 按 size 降序
}

export interface ClearResult {
  freedBytes: number;
  freedFormatted: string;
  clearedKeys: string[];
}

/** 格式化字节大小为可读字符串 */
export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
}

/**
 * 估算各 key 的存储占用（按 value 的字符串长度估算 UTF-16 码元）。
 *
 * 注意：localStorage 实际以 UTF-16 存储，1 个字符 = 2 字节。
 * 这里用 value.length * 2 粗略估算，足够用于排序和总量参考。
 */
export function estimateStorageSize(): StorageUsage {
  const keys: StorageKeyInfo[] = [];
  let total = 0;

  try {
    const all = window.localStorage;
    // 只统计本应用相关的 key（scopedStorage 会加前缀），避免统计到平台全局变量
    for (let i = 0; i < all.length; i++) {
      const key = all.key(i);
      if (!key) continue;
      const value = all.getItem(key);
      if (!value) continue;
      // UTF-16: 2 bytes per code unit
      const size = value.length * 2 + key.length * 2;
      total += size;
      keys.push({
        key,
        size,
        sizeFormatted: formatBytes(size),
        percent: (size / TOTAL_QUOTA_BYTES) * 100,
      });
    }
  } catch (e) {
    logger.warn('[storage-utils] estimate failed: ' + String(e));
  }

  keys.sort((a, b) => b.size - a.size);

  return {
    used: total,
    usedFormatted: formatBytes(total),
    total: TOTAL_QUOTA_BYTES,
    totalFormatted: formatBytes(TOTAL_QUOTA_BYTES),
    available: Math.max(0, TOTAL_QUOTA_BYTES - total),
    availableFormatted: formatBytes(Math.max(0, TOTAL_QUOTA_BYTES - total)),
    percent: Math.min(100, (total / TOTAL_QUOTA_BYTES) * 100),
    keys,
  };
}

/**
 * 安全保存：先估算剩余空间，如果写入后预计超过 90% 就给出明确错误。
 * 真正写入时捕获 QuotaExceededError 并返回结构化错误。
 */
export interface SafeSetResult {
  success: boolean;
  error?: 'quota' | 'unknown';
  errorMessage?: string;
  usageBefore?: StorageUsage;
}

export function safeSetItem(key: string, value: string): SafeSetResult {
  const usageBefore = estimateStorageSize();

  try {
    localStorage.setItem(key, value);
    return { success: true, usageBefore };
  } catch (e) {
    const name = e instanceof Error ? e.name : '';
    const message = e instanceof Error ? e.message : String(e);

    // QuotaExceededError 是常见的配额超限错误名
    const isQuota =
      name === 'QuotaExceededError' ||
      message.includes('exceeded the quota') ||
      message.includes('QuotaExceeded');

    return {
      success: false,
      error: isQuota ? 'quota' : 'unknown',
      errorMessage: message,
      usageBefore,
    };
  }
}

/**
 * 判断错误是否为配额超限。
 */
export function isQuotaError(e: unknown): boolean {
  if (e instanceof Error) {
    return (
      e.name === 'QuotaExceededError' ||
      e.message.includes('exceeded the quota') ||
      e.message.includes('QuotaExceeded')
    );
  }
  return false;
}

/**
 * 需要保留的关键配置 key（清理时不会删除）。
 * 这些 key 体积小但影响大，丢失会导致用户需要重新配置。
 */
const PRESERVE_KEY_PATTERNS = [
  /__app_ledlight_github_config/, // GitHub 同步配置
  /__app_ledlight_language/, // 语言设置
  /__app_ledlight_admin_language/,
  /__app_ledlight_admin_auth/, // 登录状态
  /__app_ledlight_admin_password/, // 后台密码
  /__app_ledlight_cookie_consent/, // Cookie 同意
  /__app_ledlight_sync_status/, // 同步状态
  /__app_ledlight_seo_settings/, // SEO 设置
  /__app_ledlight_analytics_settings/, // 统计配置（当前要保存的）
  /__app_ledlight_footer_settings/, // 页脚设置（重要全局配置）
  /__app_ledlight_translate_settings/, // 翻译服务设置
  /__app_ledlight_about_content_v1/, // 关于页内容（图文，体积大但属于核心内容）
  /__app_ledlight_advantages_v3/, // 首页优势
  /__app_ledlight_testimonials_v3/, // 客户评价
  /__app_ledlight_features_v2/, // 功能点
  /__app_ledlight_hero_slides/, // Hero 轮播配置
  /__app_ledlight_categories_v1/, // 产品分类
  /__app_ledlight_articles_v2/, // 新闻文章
  /__app_ledlight_privacy_policy_v1/, // 隐私政策
  /__app_ledlight_inquiries/, // 询盘记录
  /__app_ledlight_products_v3/, // 产品元数据镜像
  /__app_ledlight_products_migrated/,
  /__app_ledlight_product_settings_v1/,
  // 非本应用前缀的（平台全局变量），不碰
];

/**
 * 可清理的缓存类 key —— 清理后可通过重新翻译/重新统计自动恢复。
 */
const CLEARABLE_KEY_PATTERNS: { pattern: RegExp; label: string }[] = [
  { pattern: /__app_ledlight_translation_cache_v/, label: 'Translation cache' },
  { pattern: /__app_ledlight_analytics_pageviews/, label: 'Local PV stats' },
];

/**
 * 清理可重建的缓存数据（翻译缓存、本地 PV 统计等）。
 * 保留所有用户配置和内容数据。
 *
 * @returns 释放的字节数和被清理的 key 列表
 */
export function clearUnnecessaryData(): ClearResult {
  const cleared: string[] = [];
  let freed = 0;

  try {
    const all = window.localStorage;
    const toRemove: string[] = [];

    for (let i = 0; i < all.length; i++) {
      const key = all.key(i);
      if (!key) continue;

      // 只清本应用的可缓存 key
      const clearable = CLEARABLE_KEY_PATTERNS.find((c) => c.pattern.test(key));
      if (clearable) {
        const value = all.getItem(key);
        if (value) {
          freed += value.length * 2 + key.length * 2;
          toRemove.push(key);
          cleared.push(clearable.label);
        }
      }
    }

    // 真正删除
    toRemove.forEach((k) => {
      try {
        window.localStorage.removeItem(k);
      } catch {
        // ignore
      }
    });

    // 同时通知 scopedStorage 同步（如果它内部有缓存的话）
    // scopedStorage 是 localStorage 的薄封装，不需要额外操作
  } catch (e) {
    logger.warn('[storage-utils] clear failed: ' + String(e));
  }

  return {
    freedBytes: freed,
    freedFormatted: formatBytes(freed),
    clearedKeys: [...new Set(cleared)], // 去重
  };
}

/**
 * 深度清理：除了保留关键配置外，还清理站点图片（base64 大图）。
 * 站点图片可以通过重新上传或 GitHub 同步恢复。
 *
 * 警告：这是更激进的清理，会导致所有自定义上传的图片丢失。
 */
export function deepClearSiteImages(): ClearResult {
  const cleared: string[] = [];
  let freed = 0;

  try {
    const all = window.localStorage;
    const toRemove: string[] = [];

    for (let i = 0; i < all.length; i++) {
      const key = all.key(i);
      if (!key) continue;

      // 站点图片（base64 大图的主要来源）
      if (key.includes('__app_ledlight_site_images')) {
        const value = all.getItem(key);
        if (value) {
          freed += value.length * 2 + key.length * 2;
          toRemove.push(key);
          cleared.push('Site images (user uploaded)');
        }
      }
    }

    toRemove.forEach((k) => {
      try {
        window.localStorage.removeItem(k);
      } catch {
        // ignore
      }
    });
  } catch (e) {
    logger.warn('[storage-utils] deep clear failed: ' + String(e));
  }

  return {
    freedBytes: freed,
    freedFormatted: formatBytes(freed),
    clearedKeys: cleared,
  };
}

/**
 * 检查是否有足够的剩余空间写入指定大小的数据。
 * 预留 10% 安全余量。
 */
export function hasEnoughSpace(estimatedBytes: number): boolean {
  const usage = estimateStorageSize();
  const safety = TOTAL_QUOTA_BYTES * 0.1; // 10% 安全余量
  return usage.available > estimatedBytes + safety;
}

/**
 * 获取配额超限的友好提示文案（英文，i18n 由调用方处理）。
 */
export function getQuotaErrorMessage(): string {
  const usage = estimateStorageSize();
  return (
    `Local storage is full (${usage.usedFormatted} / ${usage.totalFormatted}). ` +
    `Please clear cached data to free up space, then try again.`
  );
}
