function loadFromStorage(): IBlogArticle[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && Array.isArray(parsed.data) && parsed.__version === STORAGE_VERSION) {
        return parsed.data;
      }
    }
  } catch {
    /* ignore */
  }
  // Migrate or initial load
  return [...DEFAULT_BLOG];
}

function loadSettingsFromStorage(): IBlogSettings {
  try {
    const raw = localStorage.getItem(BLOG_SETTINGS_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && typeof parsed.blogEnabled === 'boolean') {
        return { blogEnabled: parsed.blogEnabled };
      }
    }
  } catch {
    /* ignore */
  }
  return { ...DEFAULT_BLOG_SETTINGS };
}

function saveSettingsToStorage(settings: IBlogSettings): void {
  try {
    localStorage.setItem(BLOG_SETTINGS_KEY, JSON.stringify(settings));
  } catch (err) {
    logger.error('Failed to save blog settings:', String(err));
  }
}

export function useBlog(options?: { preferRemote?: boolean }) {
  const preferRemote = options?.preferRemote ?? false;
  const remoteData = useRemoteDataStore<IBlogArticle[]>('blog');
  const remoteSettings = useRemoteDataStore<IBlogSettings>('blogSettings');
  const [articles, setArticles] = useState<IBlogArticle[]>(() => loadFromStorage());
  const [settings, setSettings] = useState<IBlogSettings>(() => loadSettingsFromStorage());
  const [loading, setLoading] = useState(false);

  const persist = useCallback((items: IBlogArticle[]) => {
    try {
      localStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({ __version: STORAGE_VERSION, data: items })
      );
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      logger.error('Failed to save blog to storage:', msg);
      if (msg.includes('QuotaExceededError') || msg.includes('exceeded the quota')) {
        throw new Error(
          'Storage is full. The uploaded cover image is too large. '
          + 'Please use a smaller image or a URL instead of uploading.'
        );
      }
      throw new Error('Failed to save: ' + msg);
    }
  }, []);

  const saveArticles = useCallback((items: IBlogArticle[]) => {
    const sorted = [...items].sort((a, b) => {
      if (a.order !== b.order) return a.order - b.order;
      return new Date(b.publishDate).getTime() - new Date(a.publishDate).getTime();
    });
    try {
      persist(sorted);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      throw new Error(`Failed to save blog to storage: ${msg}`);
    }
    setArticles(sorted);
    window.dispatchEvent(new CustomEvent(BLOG_REFRESH_EVENT, { detail: sorted }));
  }, [persist]);

  const addArticle = useCallback(
    (article: Omit<IBlogArticle, 'id' | 'createdAt' | 'updatedAt'>): IBlogArticle => {
      const now = Date.now();
      const newItem: IBlogArticle = {
        ...article,
        id: `blog_${now}_${Math.random().toString(36).slice(2, 8)}`,
        createdAt: now,
        updatedAt: now,
      };
      saveArticles([...articles, newItem]);
      return newItem;
    },
    [articles, saveArticles]
  );

  const updateArticle = useCallback(
    (id: string, updates: Partial<IBlogArticle>) => {
      const updated = articles.map((a) =>
        a.id === id ? { ...a, ...updates, updatedAt: Date.now() } : a
      );
      saveArticles(updated);
    },
    [articles, saveArticles]
  );

  const deleteArticle = useCallback(
    (id: string) => {
      saveArticles(articles.filter((a) => a.id !== id));
    },
    [articles, saveArticles]
  );

  const setBlogEnabled = useCallback((enabled: boolean) => {
    const newSettings = { ...settings, blogEnabled: enabled };
    setSettings(newSettings);
    saveSettingsToStorage(newSettings);
    window.dispatchEvent(new CustomEvent('app-ledlight-blog-settings-changed', { detail: newSettings }));
  }, [settings]);

  // 监听 storage 事件（跨 tab 同步）和自定义刷新事件（GitHub pull 等）
  useEffect(() => {
    const reloadFromStorage = () => {
      try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (raw) {
          const parsed = JSON.parse(raw);
          if (parsed && Array.isArray(parsed.data) && parsed.__version === STORAGE_VERSION) {
            setArticles(parsed.data);
            return;
          }
        }
      } catch { /* ignore */ }
      setArticles([...DEFAULT_BLOG]);
    };

    const onStorage = (e: StorageEvent) => {
      if (e.key === STORAGE_KEY) {
        logger.info('[useBlog] Storage event received, reloading');
        reloadFromStorage();
      }
    };

    const onCustomRefresh = (e: Event) => {
      const detail = (e as CustomEvent<IBlogArticle[]>).detail;
      if (detail && Array.isArray(detail)) {
        setArticles(detail);
        logger.info('[useBlog] Reloaded blog from custom refresh event');
      } else {
        reloadFromStorage();
      }
    };

    const onGithubPulled = () => {
      logger.info('[useBlog] GitHub pull event received, reloading from storage');
      reloadFromStorage();
      // 重新加载设置
      setSettings(loadSettingsFromStorage());
    };

    window.addEventListener('storage', onStorage);
    window.addEventListener(BLOG_REFRESH_EVENT, onCustomRefresh);
    window.addEventListener('app-ledlight-blog-github-pulled', onGithubPulled);

    return () => {
      window.removeEventListener('storage', onStorage);
      window.removeEventListener(BLOG_REFRESH_EVENT, onCustomRefresh);
      window.removeEventListener('app-ledlight-blog-github-pulled', onGithubPulled);
    };
  }, []);

  // 远程设置数据（preferRemote 模式下使用）
  // 逻辑：以远程值为初始默认，但如果用户在后台主动 toggle 过（本地值 ≠ 默认值），则以本地值为准
  // 这样后台关闭开关后，前台立即生效，不需要等同步到 GitHub
  const displaySettings = useMemo((): IBlogSettings => {
    const hasUserToggled = settings.blogEnabled !== DEFAULT_BLOG_SETTINGS.blogEnabled;
    if (preferRemote && remoteSettings && typeof remoteSettings === 'object' && !hasUserToggled) {
      const raw = remoteSettings as unknown as Record<string, unknown>;
      return {
        blogEnabled: raw.blogEnabled !== false, // 老数据兼容：没有这个字段默认 true
      };
    }
    return settings;
  }, [preferRemote, remoteSettings, settings]);

  // 远程数据转换（preferRemote 模式下使用）
  const displayArticles = useMemo(() => {
    if (preferRemote && remoteData && Array.isArray(remoteData) && remoteData.length > 0) {
      const transformed = safeTransform('blog', () =>
        remoteData.map((raw: unknown, idx: number) => {
          const a = (raw ?? {}) as Record<string, unknown>;
          return {
            id: safeStr(a.id, `blog_remote_${idx}`),
            slug: safeStr(a.slug, `blog-${idx}`),
            coverImage: safeStr(a.coverImage || a.image, ''),
            title: safeI18n(a.title),
            summary: safeI18n(a.summary),
            content: safeI18n(a.content),
            metaTitle: safeI18n(a.metaTitle || a.seoTitle),
            metaDescription: safeI18n(a.metaDescription || a.seoDescription),
            publishDate: safeStr(a.publishDate || a.date, new Date().toISOString()),
            published: safeBool(a.published, true),
            category: safeStr(a.category, 'Guide'),
            order: safeNum(a.order ?? a.sortOrder, idx + 1),
            createdAt: safeNum(a.createdAt, Date.now()),
            updatedAt: safeNum(a.updatedAt, Date.now()),
          } as IBlogArticle;
        })
      );
      if (transformed && transformed.length > 0) {
        return [...transformed].sort((a, b) =>
          new Date(b.publishDate).getTime() - new Date(a.publishDate).getTime()
        );
      }
      logger.warn('[Blog] remote data transform failed or empty, falling back to local');
    }
    return articles;
  }, [preferRemote, remoteData, articles]);

  const getPublishedArticles = useCallback(
    () => displayArticles.filter((a) => a.published),
    [displayArticles]
  );

  return {
    articles: displayArticles,
    loading,
    blogEnabled: displaySettings.blogEnabled,
    settings: displaySettings,
    addArticle,
    updateArticle,
    deleteArticle,
    saveArticles,
    getPublishedArticles,
    setBlogEnabled,
  };
}

export default useBlog;
