import { useState, useRef } from 'react';
import { Play, Pause, Volume2, VolumeX, Maximize2, Loader2 } from 'lucide-react';
import { motion } from 'framer-motion';

interface FactoryVideoPlayerProps {
  videoUrl: string;
  title?: string;
  posterUrl?: string;
  autoPlay?: boolean;
  showControls?: boolean;
  variant?: 'home' | 'about';
}

export default function FactoryVideoPlayer({
  videoUrl,
  title = 'Factory Tour',
  posterUrl = '',
  autoPlay = true,
  showControls = true,
  variant = 'home',
}: FactoryVideoPlayerProps) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isPlaying, setIsPlaying] = useState(autoPlay);
  const [isMuted, setIsMuted] = useState(true);
  const [isLoading, setIsLoading] = useState(true);
  const [showBigPlay, setShowBigPlay] = useState(!autoPlay);

  const handlePlayPause = () => {
    const v = videoRef.current;
    if (!v) return;
    if (v.paused) {
      v.play();
      setIsPlaying(true);
      setShowBigPlay(false);
    } else {
      v.pause();
      setIsPlaying(false);
    }
  };

  const handleMuteToggle = () => {
    const v = videoRef.current;
    if (!v) return;
    v.muted = !v.muted;
    setIsMuted(v.muted);
  };

  const handleFullscreen = () => {
    const v = videoRef.current;
    if (!v) return;
    if (v.requestFullscreen) {
      v.requestFullscreen();
    } else if ((v as any).webkitEnterFullscreen) {
      (v as any).webkitEnterFullscreen();
    }
  };

  const handleLoadedData = () => {
    setIsLoading(false);
  };

  const handleVideoEnd = () => {
    setIsPlaying(false);
    if (!autoPlay) {
      setShowBigPlay(true);
    }
  };

  const isWide = variant === 'home';

  if (!videoUrl) {
    return (
      <div className={`w-full ${isWide ? 'aspect-video' : 'aspect-[4/3]'} bg-card border border-border/40 rounded-sm flex items-center justify-center`}>
        <p className="text-muted-foreground text-sm">Video not available</p>
      </div>
    );
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: '-50px' }}
      transition={{ duration: 0.6 }}
      className="relative w-full group"
    >
      {/* 视频容器 */}
      <div
        className={`relative w-full ${isWide ? 'aspect-video' : 'aspect-[4/3]'} bg-black overflow-hidden rounded-sm border border-primary/20`}
      >
        <video
          ref={videoRef}
          src={videoUrl}
          poster={posterUrl || undefined}
          className="w-full h-full object-cover"
          autoPlay={autoPlay}
          muted={isMuted}
          loop={autoPlay}
          playsInline
          controls={false}
          onLoadedData={handleLoadedData}
          onEnded={handleVideoEnd}
          onClick={handlePlayPause}
        />

        {/* 加载状态 */}
        {isLoading && (
          <div className="absolute inset-0 flex items-center justify-center bg-black/50">
            <Loader2 className="size-8 text-primary animate-spin" />
          </div>
        )}

        {/* 大播放按钮（未自动播放时显示） */}
        {showBigPlay && !isLoading && (
          <button
            onClick={handlePlayPause}
            className="absolute inset-0 flex items-center justify-center bg-black/30 hover:bg-black/40 transition-colors"
            aria-label="Play video"
          >
            <div className="size-16 md:size-20 rounded-full bg-primary/90 flex items-center justify-center shadow-lg shadow-primary/30 transition-transform hover:scale-110">
              <Play className="size-8 md:size-10 text-white ml-1" fill="white" />
            </div>
          </button>
        )}

        {/* 顶部光束装饰（工业风） */}
        <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-primary/60 to-transparent" />
        <div className="absolute bottom-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-primary/60 to-transparent" />

        {/* 左下角标题（hover 时显示） */}
        {title && (
          <div className="absolute top-3 left-3 md:top-4 md:left-4 opacity-0 group-hover:opacity-100 transition-opacity">
            <div className="px-3 py-1.5 bg-black/70 backdrop-blur-sm rounded-sm border border-primary/30">
              <span className="text-xs md:text-sm text-white/90 font-medium tracking-wide">
                {title}
              </span>
            </div>
          </div>
        )}

        {/* 控制条 */}
        {showControls && (
          <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/80 via-black/40 to-transparent p-3 md:p-4 opacity-0 group-hover:opacity-100 transition-opacity">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2 md:gap-3">
                <button
                  onClick={handlePlayPause}
                  className="text-white/90 hover:text-primary transition-colors"
                  aria-label={isPlaying ? 'Pause' : 'Play'}
                >
                  {isPlaying ? <Pause className="size-5 md:size-6" /> : <Play className="size-5 md:size-6" />}
                </button>
                <button
                  onClick={handleMuteToggle}
                  className="text-white/90 hover:text-primary transition-colors"
                  aria-label={isMuted ? 'Unmute' : 'Mute'}
                >
                  {isMuted ? <VolumeX className="size-5 md:size-6" /> : <Volume2 className="size-5 md:size-6" />}
                </button>
              </div>
              <button
                onClick={handleFullscreen}
                className="text-white/90 hover:text-primary transition-colors"
                aria-label="Fullscreen"
              >
                <Maximize2 className="size-5 md:size-6" />
              </button>
            </div>
          </div>
        )}
      </div>
    </motion.div>
  );
}
