function migrateFromLegacy(raw: unknown): IFaq[] | null {
  let arr: unknown[] = [];
  if (Array.isArray(raw)) {
    arr = raw;
  } else if (raw && typeof raw === 'object' && Array.isArray((raw as { data?: unknown[] }).data)) {
    arr = (raw as { data: unknown[] }).data;
  }
  if (!arr.length) return null;
  try {
    return arr.map((item, idx) => {
      const a = item as Record<string, unknown>;
      return {
        id: String(a.id ?? `faq_${idx}`),
        question: migrateI18n(a.question as string | I18nText),
        answer: migrateI18n(a.answer as string | I18nText),
        order: Number(a.order ?? idx + 1),
      };
    });
  } catch {
    return null;
  }
}

function readLocalFaqs(): IFaq[] {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (
        parsed.__version === STORAGE_VERSION &&
        Array.isArray(parsed.data) &&
        parsed.data.length > 0
      ) {
        return parsed.data
          .map((a: Record<string, unknown>) => ({
            ...a,
            question: migrateI18n(a.question as string | I18nText | undefined),
            answer: migrateI18n(a.answer as string | I18nText | undefined),
          }))
          .sort((a: IFaq, b: IFaq) => a.order - b.order);
      }
      const migrated = migrateFromLegacy(parsed);
      if (migrated && migrated.length > 0) {
        return migrated.sort((a, b) => a.order - b.order);
      }
    }
  } catch {
    // ignore
  }
  return DEFAULT_FAQS;
}

export function useFaqs(options?: { preferRemote?: boolean }) {
  const preferRemote = options?.preferRemote ?? false;
  const remoteData = useRemoteDataStore<IFaq[]>('faqs');
  const [faqs, setFaqs] = useState<IFaq[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (
          parsed.__version === STORAGE_VERSION &&
          Array.isArray(parsed.data) &&
          parsed.data.length > 0
        ) {
          const mapped = parsed.data.map((a: Record<string, unknown>) => ({
            ...a,
            question: migrateI18n(a.question as string | I18nText | undefined),
            answer: migrateI18n(a.answer as string | I18nText | undefined),
          }));
          return mapped.sort((a, b) => a.order - b.order);
        }
        const migrated = migrateFromLegacy(parsed);
        if (migrated && migrated.length > 0) {
          return migrated.sort((a, b) => a.order - b.order);
        }
      }
    } catch {
      // ignore
    }
    setTimeout(() => persist(DEFAULT_FAQS), 0);
    return DEFAULT_FAQS;
  });

  useEffect(() => {
    const handleGithubPulled = () => {
      try {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (saved) {
          const parsed = JSON.parse(saved);
          if (
            parsed.__version === STORAGE_VERSION &&
            Array.isArray(parsed.data) &&
            parsed.data.length > 0
          ) {
            const mapped = parsed.data.map((a: Record<string, unknown>) => ({
              ...a,
              question: migrateI18n(a.question as string | I18nText | undefined),
              answer: migrateI18n(a.answer as string | I18nText | undefined),
            }));
            setFaqs(mapped.sort((a: IFaq, b: IFaq) => a.order - b.order));
            logger.info('[Faqs] Refreshed from localStorage after GitHub pull');
          }
        }
      } catch (err) {
        logger.warn('[Faqs] Failed to refresh after GitHub pull:', String(err));
      }
    };

    window.addEventListener('app-ledlight-faqs-github-pulled', handleGithubPulled);
    return () => {
      window.removeEventListener('app-ledlight-faqs-github-pulled', handleGithubPulled);
    };
  }, []);

  const loading = false;

  const displayFaqs = useMemo(() => {
    if (preferRemote && remoteData && Array.isArray(remoteData) && remoteData.length > 0) {
      const transformed = safeTransform('faqs', () =>
        remoteData.map((raw: unknown, idx: number) => {
          const a = (raw ?? {}) as Record<string, unknown>;
          return {
            id: safeStr(a.id, `faq_remote_${idx}`),
            question: safeI18n(a.question),
            answer: safeI18n(a.answer),
            order: safeNum(a.order ?? a.sortOrder, idx + 1),
          } as IFaq;
        })
      );
      if (transformed && transformed.length > 0) {
        return transformed.sort((a, b) => a.order - b.order);
      }
      logger.warn('[Faqs] remote data transform failed or empty, falling back to local');
    }
    return faqs;
  }, [preferRemote, remoteData, faqs]);

  const persist = (items: IFaq[]) => {
    try {
      localStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({ __version: STORAGE_VERSION, data: items })
      );
    } catch {
      // ignore
    }
  };

  const saveFaqs = useCallback((items: IFaq[]) => {
    const sorted = [...items].sort((a, b) => a.order - b.order);
    try {
      persist(sorted);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      throw new Error(`Failed to save faqs to storage: ${msg}`);
    }
    setFaqs(sorted);
  }, []);

  const addFaq = useCallback(
    (faq: Omit<IFaq, 'id'>): IFaq => {
      const newItem: IFaq = {
        ...faq,
        id: `faq_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      };
      saveFaqs([...faqs, newItem]);
      return newItem;
    },
    [faqs, saveFaqs]
  );

  const updateFaq = useCallback(
    (id: string, updates: Partial<IFaq>) => {
      const updated = faqs.map((f) => (f.id === id ? { ...f, ...updates } : f));
      saveFaqs(updated);
    },
    [faqs, saveFaqs]
  );

  const deleteFaq = useCallback(
    (id: string) => {
      saveFaqs(faqs.filter((f) => f.id !== id));
    },
    [faqs, saveFaqs]
  );

  return {
    faqs: displayFaqs,
    loading,
    addFaq,
    updateFaq,
    deleteFaq,
    isUsingRemoteData: preferRemote && !!remoteData,
  };
}
