function migrateFromLegacy(raw: unknown): ITestimonial[] | null {
  let arr: unknown[] = [];
  if (Array.isArray(raw)) arr = raw;
  else if (raw && typeof raw === 'object' && Array.isArray((raw as { data?: unknown[] }).data))
    arr = (raw as { data: unknown[] }).data;
  if (!arr.length) return null;
  try {
    return arr.map((item, idx) => {
      const t = item as Record<string, unknown>;
      return {
        id: String(t.id ?? `test_${idx}`),
        customerName: migrateI18n(t.customerName as string | I18nText | undefined),
        company: String(t.company ?? ''),
        avatar: String(t.avatar ?? LOCAL_AVATARS[idx % LOCAL_AVATARS.length]),
        content: migrateI18n(t.content as string | I18nText | undefined),
        rating: Number(t.rating ?? 5),
        createdAt: Number(t.createdAt ?? Date.now() - idx * 86400000),
        isVisible: t.isVisible !== false,
      };
    });
  } catch {
    return null;
  }
}

function readLocalShowOnHomepage(): boolean {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (typeof parsed.showOnHomepage === 'boolean') return parsed.showOnHomepage;
    }
  } catch {
    // ignore
  }
  return DEFAULT_SHOW_ON_HOMEPAGE;
}

function readLocalTestimonials(): ITestimonial[] {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (
        parsed.__version === STORAGE_VERSION &&
        Array.isArray(parsed.data) &&
        parsed.data.length > 0
      ) {
        return parsed.data
          .map((t: Record<string, unknown>) => ({
            ...t,
            customerName: migrateI18n(t.customerName as string | I18nText | undefined),
            content: migrateI18n(t.content as string | I18nText | undefined),
            isVisible: t.isVisible !== false,
          }))
          .sort((a: ITestimonial, b: ITestimonial) => b.createdAt - a.createdAt);
      }
      const migrated = migrateFromLegacy(parsed);
      if (migrated && migrated.length > 0) {
        return migrated.sort((a, b) => b.createdAt - a.createdAt);
      }
    }
  } catch {
    // ignore
  }
  return DEFAULT_TESTIMONIALS;
}

export function useTestimonials(options?: { preferRemote?: boolean }) {
  const preferRemote = options?.preferRemote ?? false;
  const remoteData = useRemoteDataStore<ITestimonial[]>('testimonials');
  // 🔴 同步初始化：直接读 localStorage 作为初始值，避免首帧默认值 → 第二帧同值不同引用的重渲染
  const [testimonials, setTestimonials] = useState<ITestimonial[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (
          parsed.__version === STORAGE_VERSION &&
          Array.isArray(parsed.data) &&
          parsed.data.length > 0
        ) {
          const mapped = parsed.data.map((t: Record<string, unknown>) => ({
            ...t,
            customerName: migrateI18n(t.customerName as string | I18nText | undefined),
            content: migrateI18n(t.content as string | I18nText | undefined),
          }));
          return mapped.sort((a: ITestimonial, b: ITestimonial) => b.createdAt - a.createdAt);
        }
        const migrated = migrateFromLegacy(parsed);
        if (migrated && migrated.length > 0) {
          return migrated.sort((a, b) => b.createdAt - a.createdAt);
        }
      }
    } catch {
      // ignore
    }
    // 没有本地数据或读取失败，用默认值并持久化
    setTimeout(() => persist(DEFAULT_TESTIMONIALS), 0);
    return DEFAULT_TESTIMONIALS;
  });

  const [showOnHomepage, setShowOnHomepageState] = useState<boolean>(() =>
    readLocalShowOnHomepage()
  );

  // 🔴 监听 GitHub 数据拉取完成事件，重新从 localStorage 读取最新数据
  useEffect(() => {
    const handleGithubPulled = () => {
      try {
        const saved = localStorage.getItem(STORAGE_KEY);
        if (saved) {
          const parsed = JSON.parse(saved);
          // 更新 showOnHomepage
          if (typeof parsed.showOnHomepage === 'boolean') {
            setShowOnHomepageState(parsed.showOnHomepage);
          }
          if (
            parsed.__version === STORAGE_VERSION &&
            Array.isArray(parsed.data) &&
            parsed.data.length > 0
          ) {
            const mapped = parsed.data.map((t: Record<string, unknown>) => ({
              ...t,
              customerName: migrateI18n(t.customerName as string | I18nText | undefined),
              content: migrateI18n(t.content as string | I18nText | undefined),
            }));
            setTestimonials(
              mapped.sort((a: ITestimonial, b: ITestimonial) => b.createdAt - a.createdAt)
            );
            logger.info('[Testimonials] Refreshed from localStorage after GitHub pull');
          }
        }
      } catch (err) {
        logger.warn('[Testimonials] Failed to refresh after GitHub pull:', String(err));
      }
    };

    window.addEventListener('app-ledlight-testimonials-github-pulled', handleGithubPulled);
    return () => {
      window.removeEventListener('app-ledlight-testimonials-github-pulled', handleGithubPulled);
    };
  }, []);

  // loading 始终为 false：本地数据同步初始化完成
  const loading = false;

  const displayTestimonials = useMemo(() => {
    if (preferRemote && remoteData && Array.isArray(remoteData) && remoteData.length > 0) {
      const transformed = safeTransform('testimonials', () =>
        remoteData.map((raw: unknown, idx: number) => {
          const t = (raw ?? {}) as Record<string, unknown>;
          return {
            id: safeStr(t.id, `test_remote_${idx}`),
            customerName: safeI18n(t.customerName),
            company: safeStr(t.company, ''),
            avatar: safeStr(t.avatar, LOCAL_AVATARS[idx % LOCAL_AVATARS.length]),
            content: safeI18n(t.content),
            rating: safeNum(t.rating, 5),
            createdAt: safeNum(t.createdAt, Date.now() - idx * 86400000),
            isVisible: t.isVisible !== false,
          } as ITestimonial;
        })
      );
      if (transformed && transformed.length > 0) {
        return [...transformed].sort((a, b) => b.createdAt - a.createdAt);
      }
      logger.warn('[Testimonials] remote data transform failed or empty, falling back to local');
    }
    return testimonials;
  }, [preferRemote, remoteData, testimonials]);

  const persist = (items: ITestimonial[], showFlag?: boolean) => {
    try {
      const show = typeof showFlag === 'boolean' ? showFlag : showOnHomepage;
      localStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({ __version: STORAGE_VERSION, data: items, showOnHomepage: show })
      );
    } catch {
      // ignore
    }
  };

  const saveTestimonials = useCallback((items: ITestimonial[]) => {
    setTestimonials(items);
    persist(items);
  }, [showOnHomepage]);

  const setShowOnHomepage = useCallback((value: boolean) => {
    setShowOnHomepageState(value);
    persist(testimonials, value);
  }, [testimonials]);

  const addTestimonial = useCallback(
    (t: Omit<ITestimonial, 'id'>) => {
      const newItem: ITestimonial = {
        ...t,
        id: `test_${Date.now()}`,
      };
      saveTestimonials([newItem, ...testimonials]);
      return newItem;
    },
    [testimonials, saveTestimonials]
  );

  const updateTestimonial = useCallback(
    (id: string, updates: Partial<ITestimonial>) => {
      const updated = testimonials.map((t) => (t.id === id ? { ...t, ...updates } : t));
      saveTestimonials(updated);
    },
    [testimonials, saveTestimonials]
  );

  const deleteTestimonial = useCallback(
    (id: string) => {
      saveTestimonials(testimonials.filter((t) => t.id !== id));
    },
    [testimonials, saveTestimonials]
  );

  const visibleTestimonials = useMemo(
    () => displayTestimonials.filter((t) => t.isVisible !== false),
    [displayTestimonials]
  );

  return {
    testimonials: displayTestimonials,
    visibleTestimonials,
    showOnHomepage,
    setShowOnHomepage,
    loading,
    addTestimonial,
    updateTestimonial,
    deleteTestimonial,
    saveTestimonials,
    isUsingRemoteData: preferRemote && !!remoteData,
  };
}
