/**
 * 网站分析设置 Hook（Google Analytics + Microsoft Clarity）
 *
 * 配置存储在 localStorage，支持：
 * - GA4 测量 ID（G-XXXXXXXXXX）
 * - Microsoft Clarity 项目 ID
 * - 启用/禁用开关
 *
 * 注意：脚本注入逻辑在 src/lib/analytics-injector.ts 中
 */

import { useCallback, useEffect, useState } from 'react';
import { logger } from '@lark-apaas/client-toolkit-lite';
import { safeSetItem, isQuotaError, getQuotaErrorMessage } from '@/lib/storage-utils';

const STORAGE_KEY = '__app_ledlight_analytics_settings';

/** 保存错误类型，用于调用方区分配额问题还是其他错误 */
export type SaveErrorType = 'quota' | 'unknown';

export interface AnalyticsSettings {
  gaEnabled: boolean;
  gaMeasurementId: string;
  ga4ApiProxyUrl: string;
  clarityEnabled: boolean;
  clarityProjectId: string;
}

const DEFAULT_SETTINGS: AnalyticsSettings = {
  gaEnabled: false,
  gaMeasurementId: '',
  ga4ApiProxyUrl: '',
  clarityEnabled: false,
  clarityProjectId: '',
};

export function loadAnalyticsSettings(): AnalyticsSettings {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      return { ...DEFAULT_SETTINGS, ...parsed };
    }
  } catch (e) {
    logger.warn('[AnalyticsSettings] Failed to load: ' + String(e));
  }
  return { ...DEFAULT_SETTINGS };
}

export function saveAnalyticsSettings(settings: AnalyticsSettings): { success: boolean; errorType?: SaveErrorType; errorMessage?: string } {
  try {
    const payload = JSON.stringify(settings);
    const result = safeSetItem(STORAGE_KEY, payload);
    if (result.success) {
      logger.info('[AnalyticsSettings] Saved successfully');
      return { success: true };
    }
    // 保存失败
    logger.error('[AnalyticsSettings] Save failed: ' + (result.errorMessage ?? 'unknown'));
    if (result.error === 'quota') {
      const msg = getQuotaErrorMessage();
      return { success: false, errorType: 'quota', errorMessage: msg };
    }
    return { success: false, errorType: 'unknown', errorMessage: result.errorMessage ?? 'Unknown error' };
  } catch (e) {
    const detail = e instanceof Error ? `${e.name}: ${e.message}` : String(e);
    logger.error('[AnalyticsSettings] Save failed: ' + detail);
    if (isQuotaError(e)) {
      const msg = getQuotaErrorMessage();
      return { success: false, errorType: 'quota', errorMessage: msg };
    }
    return { success: false, errorType: 'unknown', errorMessage: detail };
  }
}

export function useAnalyticsSettings() {
  const [settings, setSettings] = useState<AnalyticsSettings>(() => loadAnalyticsSettings());

  const updateSettings = useCallback((next: AnalyticsSettings): { success: boolean; errorType?: SaveErrorType; errorMessage?: string } => {
    // 先持久化，成功后再更新 state，避免脏 state
    const result = saveAnalyticsSettings(next);
    if (result.success) {
      setSettings(next);
    }
    return result;
  }, []);

  const resetSettings = useCallback(() => {
    setSettings({ ...DEFAULT_SETTINGS });
    try {
      saveAnalyticsSettings({ ...DEFAULT_SETTINGS });
    } catch {
      // reset 失败不抛错
    }
  }, []);

  // 跨 tab 同步
  useEffect(() => {
    const handleStorage = (e: StorageEvent) => {
      if (e.key && e.key.endsWith(STORAGE_KEY)) {
        setSettings(loadAnalyticsSettings());
      }
    };
    window.addEventListener('storage', handleStorage);
    return () => window.removeEventListener('storage', handleStorage);
  }, []);

  return {
    settings,
    updateSettings,
    resetSettings,
  };
}
