/**
 * 询盘管理上下文（单例）
 *
 * 🔴 根因修复：原来的 useInquiries 是普通函数式 hook，每个组件各自 new 一个 useState，
 * 前台提交询盘后后台管理页面看不到（因为是两个独立的 state 实例）。
 * 虽然数据存在 localStorage 里，但后台页面不刷新就不会重新读取。
 *
 * 修复方案：提升到 Context 做全局单例，所有组件共享同一份 inquiries state。
 * 并且监听 storage 事件，跨 tab 也能同步。
 */

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';
import { logger } from '@lark-apaas/client-toolkit-lite';
import { format } from 'date-fns';
import {
  createIssue,
  getFileContent,
  decodeBase64Content,
  createOrUpdateFile,
  type GithubConfig,
} from '@/lib/github-api';

const STORAGE_KEY = '__app_ledlight_inquiries';
const NOTIFY_EMAIL = 'sherwin@tanjeon.com';
const SYNC_EVENT = '__app_ledlight_inquiry_sync__';
const INQUIRY_WORKER_URL = 'https://inquiry.tanjeon.com';

type InquiryMailFields = {
  name: string;
  company: string;
  email: string;
  phone?: string;
  country: string;
  product: string;
  productName?: string;
  category?: string;
  categoryName?: string;
  message: string;
  source: IInquiry['source'];
  createdAt: number;
};

export function buildMailto(inquiry: InquiryMailFields, toEmail = NOTIFY_EMAIL): string {
  const subject = `Inquiry from ${inquiry.name || inquiry.company || 'Customer'}`;
  const body = [
    'New Inquiry Received',
    '',
    `Name: ${inquiry.name || '-'}`,
    `Company: ${inquiry.company || '-'}`,
    `Email: ${inquiry.email}`,
    `Country: ${inquiry.country || '-'}`,
    `Product: ${inquiry.productName || inquiry.product || '-'}`,
    ...(inquiry.category || inquiry.categoryName
      ? [`Category: ${inquiry.categoryName || inquiry.category}`]
      : []),
    '',
    'Message:',
    inquiry.message || '-',
    '',
    `Source: ${inquiry.source}`,
    `Date: ${format(inquiry.createdAt, 'yyyy-MM-dd HH:mm:ss')}`,
  ].join('\n');
  return `mailto:${encodeURIComponent(toEmail)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
}

export interface IInquiry {
  id: string;
  name: string;
  company: string;
  email: string;
  phone: string;
  country: string;
  product: string;
  productName?: string;
  category?: string;
  categoryName?: string;
  message: string;
  source: 'home' | 'contact' | 'product';
  status: 'unread' | 'read' | 'replied';
  createdAt: number;
  githubIssueUrl?: string;
  githubIssueNumber?: number;
  /** 邮件发送状态：success / failed / pending / 'not-sent' */
  emailStatus?: 'success' | 'failed' | 'pending' | 'not-sent';
  /** 邮件发送失败原因 */
  emailError?: string;
  /** Issue 同步状态：success / failed / pending / 'not-sent' */
  githubSyncStatus?: 'success' | 'failed' | 'pending' | 'not-sent';
  /** Issue 同步失败原因 */
  githubSyncError?: string;
  /** 邮件发送渠道（成功时记录） */
  emailChannel?: 'worker' | 'github-issue';
}

function loadInquiries(): IInquiry[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        return parsed;
      }
    }
  } catch (e) {
    logger.error('[InquiryContext] Failed to load inquiries from storage: ' + String(e));
  }
  return [];
}

function saveInquiries(list: IInquiry[]) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(list));
    logger.info(`[InquiryContext] Saved ${list.length} inquiries to localStorage`);
    // 🔴 保存后立即派发自定义事件，确保同-tab 内其他实例/组件立刻感知到新数据
    // （storage 事件只在跨-tab 时触发，同-tab 不触发）
    try {
      window.dispatchEvent(new CustomEvent(SYNC_EVENT));
    } catch {
      // SSR / 老浏览器兜底，不影响主流程
    }
  } catch (e) {
    logger.error('[InquiryContext] Failed to save inquiries to localStorage: ' + String(e));
    throw e;
  }
}

interface InquiryContextValue {
  inquiries: IInquiry[];
  loaded: boolean;
  addInquiry: (data: Omit<IInquiry, 'id' | 'status' | 'createdAt' | 'githubSyncStatus' | 'emailStatus'>) => IInquiry;
  updateStatus: (id: string, status: IInquiry['status']) => void;
  deleteInquiry: (id: string) => void;
  clearAll: () => void;
  unreadCount: number;
  totalCount: number;
  buildMailto: typeof buildMailto;
  notifyEmail: string;
  /** 通过 Cloudflare Worker 发送询盘邮件（主邮件渠道） */
  sendInquiryEmail: (inquiry: IInquiry) => Promise<boolean>;
  /**
   * 发送询盘邮件（仅通过 Cloudflare Worker）
   * 1. 尝试 Cloudflare Worker 邮件服务
   * 2. 失败时返回错误信息，不再自动回退到 GitHub Issue
   * 3. 返回 { success, channel, error? }
   */
  sendInquiryWithFallback: (inquiry: IInquiry) => Promise<{ success: boolean; channel: 'worker' | 'none'; error?: string }>;
  /** @deprecated 保留用于向后兼容，不再作为邮件通知主渠道 */
  sendInquiryToGithubIssue: (inquiry: IInquiry, githubConfig: GithubConfig) => Promise<boolean>;
  syncInquiryToGithubData: (inquiry: IInquiry, githubConfig: GithubConfig) => Promise<boolean>;
  refresh: () => void;
}

const InquiryContext = createContext<InquiryContextValue | null>(null);

export function InquiryProvider({ children }: { children: ReactNode }) {
  const [inquiries, setInquiries] = useState<IInquiry[]>([]);
  const [loaded, setLoaded] = useState(false);

  // 初始加载
  useEffect(() => {
    setInquiries(loadInquiries());
    setLoaded(true);
  }, []);

  // 监听同步事件（跨 tab + 同 tab 双保险）
  // - storage 事件：跨 tab 时由浏览器自动派发（同-tab 修改不触发）
  // - CustomEvent：同-tab 内手动派发，确保本页任何组件修改后其他组件立刻感知
  useEffect(() => {
    const reload = () => {
      logger.info('[InquiryContext] Sync event received, reloading inquiries');
      setInquiries(loadInquiries());
    };
    const handleStorage = (e: StorageEvent) => {
      if (e.key && e.key.endsWith(STORAGE_KEY)) {
        reload();
      }
    };
    const handleCustom = () => reload();
    window.addEventListener('storage', handleStorage);
    window.addEventListener(SYNC_EVENT, handleCustom as EventListener);
    return () => {
      window.removeEventListener('storage', handleStorage);
      window.removeEventListener(SYNC_EVENT, handleCustom as EventListener);
    };
  }, []);

  // 手动刷新（某些特殊场景下从 localStorage 重新读取）
  const refresh = useCallback(() => {
    setInquiries(loadInquiries());
  }, []);

  const addInquiry = useCallback(
    (data: Omit<IInquiry, 'id' | 'status' | 'createdAt' | 'githubSyncStatus' | 'emailStatus'>): IInquiry => {
      const newItem: IInquiry = {
        ...data,
        id: `inq_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
        status: 'unread',
        createdAt: Date.now(),
        emailStatus: 'not-sent',
        githubSyncStatus: 'not-sent',
      };
      logger.info(
        `[InquiryContext] Adding new inquiry: id=${newItem.id}, source=${newItem.source}, ` +
        `email=${newItem.email}, name=${newItem.name || newItem.company || 'n/a'}`
      );
      setInquiries((prev) => {
        const next = [newItem, ...prev];
        try {
          saveInquiries(next);
        } catch (e) {
          logger.error(
            '[InquiryContext] FAILED to save inquiry to localStorage! ' +
            'The inquiry is only in memory and will be lost on page refresh. Error: ' + String(e)
          );
        }
        return next;
      });
      return newItem;
    },
    []
  );

  /**
   * 通过 Cloudflare Worker 发送询盘邮件（主邮件通知渠道）
   * Worker URL: https://inquiry.tanjeon.com
   * 失败时记录错误信息到询盘记录，方便后台查看
   *
   * 错误排查要点：
   * - 502 Bad Gateway: Worker 后端故障或部署有问题
   * - CORS error: Worker 未处理 OPTIONS 预检请求
   * - NetworkError / Failed to fetch: DNS 解析失败或网络不通
   * - timeout: Worker 响应超时（默认 15s）
   */
  const sendInquiryEmail = useCallback(
    async (inquiry: IInquiry): Promise<boolean> => {
      logger.info(
        `[InquiryContext] Sending inquiry email via Cloudflare Worker: id=${inquiry.id}, ` +
        `email=${inquiry.email}, worker=${INQUIRY_WORKER_URL}`
      );

      // 先标记为 pending
      setInquiries((prev) =>
        prev.map((i) =>
          i.id === inquiry.id ? { ...i, emailStatus: 'pending' as const } : i
        )
      );

      const payload = {
        name: inquiry.name || '',
        email: inquiry.email || '',
        phone: inquiry.phone || '',
        company: inquiry.company || '',
        product: inquiry.productName || inquiry.product || '',
        country: inquiry.country || '',
        message: inquiry.message || '',
      };

      logger.info(
        `[InquiryContext] Worker request payload: ` +
        `name=${payload.name || 'n/a'}, company=${payload.company || 'n/a'}, ` +
        `email=${payload.email}, product=${payload.product || 'n/a'}, ` +
        `msgLen=${payload.message.length}`
      );

      // AbortController 超时控制（15秒）
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 15000);

      try {
        const res = await fetch(INQUIRY_WORKER_URL, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
          },
          body: JSON.stringify(payload),
          signal: controller.signal,
          // 不使用 no-cors，我们需要读取响应状态
          mode: 'cors',
        });

        clearTimeout(timeoutId);

        logger.info(
          `[InquiryContext] Worker response: status=${res.status}, ` +
          `statusText=${res.statusText}, ok=${res.ok}, ` +
          `contentType=${res.headers.get('content-type') || 'n/a'}`
        );

        let result: { success?: boolean; message?: string; id?: string; error?: string } = {};
        let rawText = '';
        try {
          rawText = await res.text();
          logger.info(`[InquiryContext] Worker raw response body (first 500 chars): ${rawText.slice(0, 500)}`);
          if (rawText) {
            result = JSON.parse(rawText);
          }
        } catch (parseErr) {
          logger.warn(
            `[InquiryContext] Worker response is not valid JSON: ${String(parseErr)}. ` +
            `Will use HTTP status code to determine success.`
          );
        }

        if (res.ok && result.success !== false && result.error === undefined) {
          logger.info(
            `[InquiryContext] Inquiry email sent successfully via Worker, ` +
            `messageId=${result.id || 'unknown'}`
          );
          setInquiries((prev) => {
            const next = prev.map((i) =>
              i.id === inquiry.id
                ? {
                    ...i,
                    emailStatus: 'success' as const,
                    emailError: undefined,
                    emailChannel: 'worker' as const,
                  }
                : i
            );
            saveInquiries(next);
            return next;
          });
          return true;
        } else {
          const errMsg =
            result.message ||
            result.error ||
            `HTTP ${res.status} ${res.statusText || '(no status text)'}`;
          logger.warn(
            `[InquiryContext] Inquiry email sending failed (Worker rejected): ${errMsg}. ` +
            `status=${res.status}, success=${result.success}, error=${result.error || 'n/a'}`
          );
          setInquiries((prev) => {
            const next = prev.map((i) =>
              i.id === inquiry.id
                ? {
                    ...i,
                    emailStatus: 'failed' as const,
                    emailError: `Worker: ${errMsg}`,
                  }
                : i
            );
            saveInquiries(next);
            return next;
          });
          return false;
        }
      } catch (err) {
        clearTimeout(timeoutId);
        const errMsg = err instanceof Error ? err.message : String(err);
        const isAbort = err instanceof DOMException && err.name === 'AbortError';
        const isCors = errMsg.includes('CORS') || errMsg.includes('cors') || errMsg.includes('Failed to fetch');
        const isNetwork = errMsg.includes('Network') || errMsg === 'Failed to fetch';

        logger.error(
          `[InquiryContext] Inquiry email send error: ${errMsg}. ` +
          `isAbort=${isAbort}, isCors=${isCors}, isNetwork=${isNetwork}. ` +
          `Worker URL: ${INQUIRY_WORKER_URL}`
        );

        const finalErrMsg = isAbort
          ? `Worker timeout after 15s (${INQUIRY_WORKER_URL})`
          : isCors
            ? `CORS error from Worker (${INQUIRY_WORKER_URL}) — worker may not be configured for cross-origin requests`
            : `Worker request failed: ${errMsg}`;

        setInquiries((prev) => {
          const next = prev.map((i) =>
            i.id === inquiry.id
              ? {
                  ...i,
                  emailStatus: 'failed' as const,
                  emailError: finalErrMsg,
                }
              : i
          );
          saveInquiries(next);
          return next;
        });
        return false;
      }
    },
    []
  );

  /**
   * 将询盘同步为 GitHub Issue（保留用于向后兼容，不再作为邮件通知主渠道）
   * 失败时记录错误信息到询盘记录，方便后台查看
   */
  const sendInquiryToGithubIssue = useCallback(
    async (inquiry: IInquiry, githubConfig: GithubConfig): Promise<boolean> => {
      // 强制直连：去掉 workerUrl，让 ghRequest 走 api.github.com 直连模式
      const directConfig: GithubConfig = {
        ...githubConfig,
        workerUrl: undefined, // 清空 Worker URL，强制直连
      };

      logger.info(
        `[InquiryContext] Sending inquiry ${inquiry.id} to GitHub Issue (DIRECT mode), ` +
        `owner=${directConfig.owner}, repo=${directConfig.repo}, ` +
        `hasToken=${!!directConfig.token}`
      );

      // Token 为空时直接失败，给出明确原因
      if (!directConfig.token) {
        logger.error(
          '[InquiryContext] Cannot create GitHub Issue: token is empty. ' +
          'Please go to Admin > GitHub Sync and enter your Personal Access Token.'
        );
        setInquiries((prev) =>
          prev.map((i) =>
            i.id === inquiry.id
              ? {
                  ...i,
                  githubSyncStatus: 'failed' as const,
                  githubSyncError: 'GitHub Token not configured. Please enter your Personal Access Token in Admin > GitHub Sync.',
                }
              : i
          )
        );
        return false;
      }

      // 先标记为 pending
      setInquiries((prev) =>
        prev.map((i) =>
          i.id === inquiry.id ? { ...i, githubSyncStatus: 'pending' as const } : i
        )
      );

       try {
         const productLabel = inquiry.productName || inquiry.product || 'General';
         // 🔴 强制保证标题以 "[Inquiry] " 开头（workflow 依赖此前缀触发）
         // 即使上游传入的 name/company 为空或奇怪，也不会丢失前缀
         let title = `[Inquiry] ${inquiry.name || inquiry.company || 'Customer'} - ${productLabel}`;
         // 双重保险：如果因为某种原因（如上游改动）前缀丢失，自动补上
         if (!title.startsWith('[Inquiry]')) {
           title = `[Inquiry] ${title}`;
         }
         // 避免 [Inquiry][Inquiry] 重复前缀
         title = title.replace(/^\[Inquiry\]\s*\[Inquiry\]\s*/i, '[Inquiry] ');
        const body = [
          '## Inquiry Details',
          '',
          `- **Name**: ${inquiry.name || '-'}`,
          `- **Email**: ${inquiry.email}`,
          `- **Company**: ${inquiry.company || '-'}`,
          `- **Country**: ${inquiry.country || '-'}`,
          `- **Product**: ${inquiry.productName || inquiry.product || '-'}`,
          ...(inquiry.category ? [`- **Category**: ${inquiry.categoryName || inquiry.category}`] : []),
          `- **Source**: ${inquiry.source}`,
          `- **Submitted At**: ${format(inquiry.createdAt, 'yyyy-MM-dd HH:mm:ss')}`,
          '',
          '## Message',
          '',
          inquiry.message || '-',
        ].join('\n');

        logger.info(
          `[InquiryContext] Issue payload: title="${title}", labels=["inquiry"], ` +
          `body length=${body.length} chars`
        );

        const result = await createIssue(directConfig, title, body, ['inquiry']);

        if (result.success && result.issueUrl) {
          logger.info(`[InquiryContext] GitHub Issue created successfully: ${result.issueUrl}`);
          setInquiries((prev) => {
            const next = prev.map((i) =>
              i.id === inquiry.id
                ? {
                    ...i,
                    githubIssueUrl: result.issueUrl!,
                    githubIssueNumber: result.issueNumber,
                    githubSyncStatus: 'success' as const,
                    githubSyncError: undefined,
                  }
                : i
            );
            saveInquiries(next);
            return next;
          });
          return true;
        } else {
          const errMsg = result.message || 'Unknown error';
          logger.warn(`[InquiryContext] GitHub Issue creation failed: ${errMsg}`);
          setInquiries((prev) => {
            const next = prev.map((i) =>
              i.id === inquiry.id
                ? {
                    ...i,
                    githubSyncStatus: 'failed' as const,
                    githubSyncError: errMsg,
                  }
                : i
            );
            saveInquiries(next);
            return next;
          });
          return false;
        }
      } catch (err) {
        const errMsg = err instanceof Error ? err.message : String(err);
        logger.error(`[InquiryContext] GitHub Issue creation error: ${errMsg}`);
        setInquiries((prev) => {
          const next = prev.map((i) =>
            i.id === inquiry.id
              ? {
                  ...i,
                  githubSyncStatus: 'failed' as const,
                  githubSyncError: errMsg,
                }
              : i
          );
          saveInquiries(next);
          return next;
        });
        return false;
      }
    },
    []
  );

  /**
   * 发送询盘邮件（仅通过 Cloudflare Worker）
   *
   * 注意：不再自动回退到 GitHub Issue。
   * Worker 失败时返回错误信息，前台展示 mailto 兜底按钮让用户手动发送。
   *
   * @returns { success, channel, error? }
   *   - success: Worker 是否发送成功
   *   - channel: 成功渠道为 'worker'，失败为 'none'
   *   - error: 错误信息（仅失败时有）
   */
  const sendInquiryWithFallback = useCallback(
    async (
      inquiry: IInquiry
    ): Promise<{ success: boolean; channel: 'worker' | 'none'; error?: string }> => {
      logger.info(
        `[InquiryContext] sendInquiryWithFallback (Worker only): id=${inquiry.id}`
      );

      // 仅尝试 Cloudflare Worker
      const workerOk = await sendInquiryEmail(inquiry);
      if (workerOk) {
        return { success: true, channel: 'worker' };
      }

      logger.warn(
        `[InquiryContext] Worker email failed. No auto-fallback to GitHub Issue. ` +
        `User will be offered mailto as manual fallback.`
      );

      const finalError =
        inquiry.emailError ||
        'Email notification service unavailable. Please use the email button to send manually.';

      return { success: false, channel: 'none', error: finalError };
    },
    [sendInquiryEmail]
  );

  /**
   * 将询盘追加到 GitHub 仓库的 data/inquiries.json
   * 实现跨浏览器/设备同步：不同浏览器打开后台都能看到所有询盘
   *
   * 流程：读取远程文件 → 追加新询盘 → 写回
   * 失败不影响本地存储，只是后台其他浏览器暂时看不到
   */
  const syncInquiryToGithubData = useCallback(
    async (inquiry: IInquiry, githubConfig: GithubConfig): Promise<boolean> => {
      logger.info(
        `[InquiryContext] Syncing inquiry ${inquiry.id} to GitHub data/inquiries.json, ` +
        `owner=${githubConfig.owner}, repo=${githubConfig.repo}`
      );

      try {
        // 1. 读取远程 data/inquiries.json（可能不存在）
        let remoteList: IInquiry[] = [];
        const existing = await getFileContent(githubConfig, 'data/inquiries.json');
        if (existing && existing.content) {
          try {
            const decoded = decodeBase64Content(existing.content);
            const parsed = JSON.parse(decoded);
            if (Array.isArray(parsed)) {
              remoteList = parsed;
            }
          } catch (parseErr) {
            logger.warn(
              `[InquiryContext] Failed to parse remote inquiries.json, will overwrite: ${String(parseErr)}`
            );
          }
        } else {
          logger.info('[InquiryContext] data/inquiries.json not found on GitHub, will create new file');
        }

        // 2. 检查是否已存在（避免重复提交）
        const exists = remoteList.some((i) => i.id === inquiry.id);
        if (exists) {
          logger.info(`[InquiryContext] Inquiry ${inquiry.id} already exists in remote, skipping`);
          return true;
        }

        // 3. 追加新询盘（最新的在前）
        const nextList = [inquiry, ...remoteList];
        const content = JSON.stringify(nextList, null, 2);

        // 4. 写回 GitHub
        const result = await createOrUpdateFile(
          githubConfig,
          'data/inquiries.json',
          content,
          `New inquiry from ${inquiry.name || inquiry.company || 'customer'}`,
          false
        );

        if (result.success) {
          logger.info(
            `[InquiryContext] Inquiry synced to data/inquiries.json successfully, ` +
            `commit=${result.commit.sha?.slice?.(0, 7) || 'unknown'}, ` +
            `total=${nextList.length} inquiries`
          );
          // 同步成功后更新本地记录的同步状态
          setInquiries((prev) => {
            const next = prev.map((i) =>
              i.id === inquiry.id
                ? { ...i, githubSyncStatus: 'success' as const, githubSyncError: undefined }
                : i
            );
            saveInquiries(next);
            return next;
          });
          return true;
        }
        return false;
      } catch (err) {
        const errMsg = err instanceof Error ? err.message : String(err);
        logger.error(`[InquiryContext] Failed to sync inquiry to data/inquiries.json: ${errMsg}`);
        // 不抛出，失败不影响本地存储和 Issue 通知
        return false;
      }
    },
    []
  );

  const updateStatus = useCallback((id: string, status: IInquiry['status']) => {
    setInquiries((prev) => {
      const next = prev.map((i) => (i.id === id ? { ...i, status } : i));
      saveInquiries(next);
      return next;
    });
  }, []);

  const deleteInquiry = useCallback((id: string) => {
    setInquiries((prev) => {
      const next = prev.filter((i) => i.id !== id);
      saveInquiries(next);
      return next;
    });
  }, []);

  const clearAll = useCallback(() => {
    setInquiries([]);
    saveInquiries([]);
  }, []);

  const unreadCount = useMemo(
    () => inquiries.filter((i) => i.status === 'unread').length,
    [inquiries]
  );

  const value = useMemo<InquiryContextValue>(
    () => ({
      inquiries,
      loaded,
      addInquiry,
      updateStatus,
      deleteInquiry,
      clearAll,
      unreadCount,
      totalCount: inquiries.length,
      buildMailto,
      notifyEmail: NOTIFY_EMAIL,
      sendInquiryEmail,
      sendInquiryWithFallback,
      sendInquiryToGithubIssue,
      syncInquiryToGithubData,
      refresh,
    }),
    [
      inquiries,
      loaded,
      addInquiry,
      updateStatus,
      deleteInquiry,
      clearAll,
      unreadCount,
      sendInquiryEmail,
      sendInquiryWithFallback,
      sendInquiryToGithubIssue,
      syncInquiryToGithubData,
      refresh,
    ]
  );

  return (
    <InquiryContext.Provider value={value}>
      {children}
    </InquiryContext.Provider>
  );
}

export function useInquiries(): InquiryContextValue {
  const ctx = useContext(InquiryContext);
  if (!ctx) {
    throw new Error('useInquiries must be used within InquiryProvider');
  }
  return ctx;
}
