// 移除平台注入的底部署名（豆包/妙搭水印）
// CSS 为主，JS 兜底：CSS 先藏住避免闪烁，JS 定期扫描主动移除 DOM 节点
// 🔴 不使用 MutationObserver（可能导致页面闪烁和性能问题）
// 🔴 极简实现：只做关键词匹配 + 定期扫描，出错即停止

const KEYWORDS = [
  'doubao-watermark', 'doubao-watermark-mobile',
  'miaoda-watermark', 'apaas-watermark', 'lark-watermark',
];

function tryRemoveWatermarks(): void {
  if (typeof document === 'undefined') return;

  try {
    // 1. 直接按已知自定义元素名移除
    for (const tag of KEYWORDS) {
      const els = document.getElementsByTagName(tag);
      // 转数组操作，避免 HTMLCollection 动态变化问题
      const arr = Array.from(els);
      for (const el of arr) {
        try {
          (el as HTMLElement).style.setProperty('display', 'none', 'important');
          el.remove();
        } catch { /* ignore */ }
      }
    }

    // 2. 扫描 body 直接子元素中的固定定位水印
    const bodyChildren = document.body.children;
    for (let i = bodyChildren.length - 1; i >= 0; i--) {
      const el = bodyChildren[i] as HTMLElement;
      if (el.id === 'root') continue;
      try {
        const style = window.getComputedStyle(el);
        if (style.position === 'fixed' || style.position === 'sticky') {
          const text = el.textContent?.trim().toLowerCase() || '';
          const cls = (el.className || '').toString().toLowerCase();
          const tag = el.tagName.toLowerCase();
          if (
            text.includes('豆包') || text.includes('妙搭') ||
            text.includes('doubao') || text.includes('miaoda') ||
            cls.includes('watermark') || cls.includes('doubao') || cls.includes('miaoda') ||
            tag.includes('watermark') || tag.includes('doubao') || tag.includes('miaoda')
          ) {
            el.style.setProperty('display', 'none', 'important');
            el.remove();
          }
        }
      } catch { /* ignore */ }
    }
  } catch {
    // 静默失败，不影响主应用
  }
}

export function setupWatermarkRemover(): () => void {
  if (typeof document === 'undefined') return () => {};

  // 立即执行一次
  tryRemoveWatermarks();

  // 只保留一个定时器，每 2 秒扫一次（覆盖延迟注入场景）
  // 🔴 不用 MutationObserver，避免性能问题和闪烁
  const intervalId = window.setInterval(tryRemoveWatermarks, 2000);

  // 页面加载后多扫几次
  const onLoad = () => {
    tryRemoveWatermarks();
    setTimeout(tryRemoveWatermarks, 1000);
    setTimeout(tryRemoveWatermarks, 3000);
    setTimeout(tryRemoveWatermarks, 5000);
  };

  if (document.readyState === 'complete') {
    onLoad();
  } else {
    window.addEventListener('load', onLoad, { once: true });
  }

  return () => {
    clearInterval(intervalId);
    window.removeEventListener('load', onLoad);
  };
}
