/**
 * 前台分析脚本注入器（GA4 + Microsoft Clarity）
 *
 * 根据 useAnalyticsSettings 的配置，动态注入/移除分析脚本。
 * 在 App 根组件中调用一次即可。
 */

import { logger } from '@lark-apaas/client-toolkit-lite';
import type { AnalyticsSettings } from '@/hooks/useAnalyticsSettings';

const GA_SCRIPT_ID = '__app_ledlight_ga_script__';
const GA_INIT_ID = '__app_ledlight_ga_init__';
const CLARITY_SCRIPT_ID = '__app_ledlight_clarity_script__';

function removeScript(id: string) {
  const el = document.getElementById(id);
  if (el && el.parentNode) {
    el.parentNode.removeChild(el);
  }
}

/**
 * 注入 GA4 gtag.js 脚本
 * 如果已经注入过且 measurementId 未变，则不重复注入
 */
export function injectGA(measurementId: string, enabled: boolean) {
  try {
    // 先移除旧的（可能 ID 变了）
    removeScript(GA_SCRIPT_ID);
    removeScript(GA_INIT_ID);
    // 清掉全局 gtag / dataLayer
    if ((window as unknown as Record<string, unknown>).dataLayer) {
      try {
        (window as unknown as Record<string, unknown>).dataLayer = undefined;
      } catch {
        /* noop */
      }
    }

    if (!enabled || !measurementId || !measurementId.trim()) {
      logger.info('[Analytics] GA4 disabled or no measurement ID, skipping');
      return;
    }

    const id = measurementId.trim();

    // 1. 异步 gtag.js
    const s1 = document.createElement('script');
    s1.id = GA_SCRIPT_ID;
    s1.async = true;
    s1.src = `https://www.googletagmanager.com/gtag/js?id=${encodeURIComponent(id)}`;
    document.head.appendChild(s1);

    // 2. 初始化 dataLayer + gtag
    const s2 = document.createElement('script');
    s2.id = GA_INIT_ID;
    s2.textContent = `
      window.dataLayer = window.dataLayer || [];
      function gtag(){dataLayer.push(arguments);}
      window.gtag = gtag;
      gtag('js', new Date());
      gtag('config', '${id.replace(/'/g, "\\'")}', { send_page_view: false });
    `;
    document.head.appendChild(s2);

    logger.info(`[Analytics] GA4 injected with ID: ${id}`);
  } catch (e) {
    logger.warn('[Analytics] injectGA error: ' + String(e));
  }
}

/**
 * 注入 Microsoft Clarity 脚本
 */
export function injectClarity(projectId: string, enabled: boolean) {
  try {
    removeScript(CLARITY_SCRIPT_ID);

    if (!enabled || !projectId || !projectId.trim()) {
      logger.info('[Analytics] Clarity disabled or no project ID, skipping');
      return;
    }

    const id = projectId.trim();

    const s = document.createElement('script');
    s.id = CLARITY_SCRIPT_ID;
    s.textContent = `
      (function(c,l,a,r,i,t,y){
        c[a]=c[a]||function(){(c[a].q=c[a].q||[]).push(arguments)};
        t=l.createElement(r);t.async=1;t.src="https://www.clarity.ms/tag/"+i;
        y=l.getElementsByTagName(r)[0];y.parentNode.insertBefore(t,y);
      })(window, document, "clarity", "script", "${id.replace(/"/g, '\\"')}");
    `;
    document.head.appendChild(s);

    logger.info(`[Analytics] Clarity injected with ID: ${id}`);
  } catch (e) {
    logger.warn('[Analytics] injectClarity error: ' + String(e));
  }
}

/**
 * 发送 SPA 路由变化的 page_view 事件给 GA4
 * 如果 GA 未配置则静默忽略
 */
export function sendPageView(path: string, title?: string) {
  const w = window as unknown as Record<string, unknown>;
  if (typeof w.gtag === 'function') {
    try {
      (w.gtag as (...args: unknown[]) => void)('event', 'page_view', {
        page_path: path,
        page_title: title || document.title,
        page_location: window.location.href,
      });
      logger.info(`[Analytics] GA4 page_view: ${path}`);
    } catch (e) {
      logger.warn('[Analytics] GA4 page_view error: ' + String(e));
    }
  }
}

/**
 * 根据配置统一注入所有分析脚本
 */
export function applyAnalyticsScripts(settings: AnalyticsSettings) {
  injectGA(settings.gaMeasurementId, settings.gaEnabled);
  injectClarity(settings.clarityProjectId, settings.clarityEnabled);
}
