import { StrictMode, Suspense, lazy, Component, type ComponentType, type ReactNode } from "react";
import { createRoot } from "react-dom/client";
import { BrowserRouter } from "react-router-dom";
import { ErrorBoundary } from "react-error-boundary";
import { logger } from "@lark-apaas/client-toolkit-lite";
import App from "./app";
import { getDynamicBasename } from "./utils/basename";
import "./index.css";
import { setupWatermarkRemover } from "./utils/watermark-remover";
import { useNavigate } from 'react-router-dom';

// 尽早启动水印移除器，在 React 渲染前就开始监听和清理平台注入元素
setupWatermarkRemover();

// GitHub Pages SPA fallback 路径恢复：
(function restoreSpaRedirect() {
  if (typeof window === 'undefined') return;
  try {
    const redirect = sessionStorage.getItem('spa-redirect');
    if (redirect && redirect !== '/') {
      sessionStorage.removeItem('spa-redirect');
      window.history.replaceState(null, '', redirect);
    }
  } catch {
    // sessionStorage 不可用时忽略
  }
})();

// 动态计算 basename（try-catch 兜底，防止 basename 计算异常导致整页白屏）
let BASENAME = '/';
try {
  BASENAME = getDynamicBasename() || '/';
} catch (e) {
  logger.error('getDynamicBasename failed, fallback to /:', String(e));
  BASENAME = '/';
}

/**
 * 判断是否为 chunk 加载失败错误
 */
function isChunkLoadError(error: unknown): boolean {
  if (!error) return false;
  const msg = typeof error === 'string' ? error : (error as Error).message || String(error);
  return (
    msg.includes('Loading chunk') ||
    msg.includes('chunk') ||
    msg.includes('Failed to fetch') ||
    msg.includes('NetworkError') ||
    msg.includes('error loading dynamically imported module') ||
    msg.includes('import')
  );
}

/**
 * 强制刷新失效的 chunk（部署新版本后旧 chunk 404 场景）
 * 通过在 URL 后加时间戳 query 参数绕过 HTTP 缓存
 */
function bustChunkCache(): void {
  try {
    // 找到所有加载失败的 script/link 标签并重试
    const scripts = document.querySelectorAll('script[src]');
    scripts.forEach((el) => {
      const src = (el as HTMLScriptElement).src;
      if (src.includes('.js') && !src.includes('?')) {
        // 标记但不直接改 src（避免重复执行）
        el.setAttribute('data-cache-bust', '1');
      }
    });
  } catch {
    // 忽略
  }
}

/**
 * 带重试功能的 React.lazy 包装器（V210 强化版）
 * 解决代码分割 chunk 加载失败（网络波动/CDN 故障/版本切换后旧 chunk 失效）导致白屏的问题
 * - 自动重试 4 次（指数退避：400ms / 800ms / 1600ms / 3200ms）
 * - 第 3 次重试开始强制 cache-bust（绕过 HTTP 缓存）
 * - 部署新版本后旧 chunk 404 场景下，最终触发整页刷新获取最新资源
 * - 仍失败则抛出错误由 ErrorBoundary 兜底
 */
export function lazyWithRetry<T extends ComponentType<any>>(
  factory: () => Promise<{ default: T }>,
  maxRetries = 4,
): ReturnType<typeof lazy<T>> {
  let attempts = 0;
  let originalFactory: (() => Promise<{ default: T }>) | null = null;

  const retryFactory = (): Promise<{ default: T }> => {
    attempts++;
    const currentFactory = factory;

    return currentFactory().catch((error) => {
      // 非 chunk 加载错误（如代码运行时错误）不重试，直接抛出
      if (!isChunkLoadError(error) && attempts > 1) {
        throw error;
      }

      if (attempts <= maxRetries) {
        const backoff = 400 * Math.pow(2, attempts - 1); // 指数退避
        logger.warn(
          `[lazyWithRetry] Chunk load failed, retry ${attempts}/${maxRetries} in ${backoff}ms:`,
          String(error),
        );

        // 第 3 次及以后的重试：触发 cache-bust 绕过 HTTP 缓存
        if (attempts >= 2) {
          bustChunkCache();
        }

        // 第 4 次重试仍失败且是典型的 chunk 加载错误 → 强制整页刷新（部署新版本后旧 chunk 404 场景）
        if (attempts === maxRetries && isChunkLoadError(error)) {
          logger.warn('[lazyWithRetry] Final retry failed, triggering full page reload for fresh chunks');
          // 用 setTimeout 避免在 Promise 链中同步 reload 导致的状态混乱
          setTimeout(() => {
            window.location.reload();
          }, 300);
        }

        return new Promise<{ default: T }>((resolve, reject) => {
          setTimeout(() => {
            retryFactory().then(resolve).catch(reject);
          }, backoff);
        });
      }

      logger.error(
        `[lazyWithRetry] Chunk load failed after ${maxRetries} retries:`,
        String(error),
      );
      throw error;
    });
  };

  return lazy(retryFactory);
}

/**
 * 全局加载兜底（深色工业风，与站点风格一致）
 * 用于 Suspense fallback，防止 lazy 组件加载时空白
 */
function GlobalSuspenseFallback() {
  return (
    <div className="flex min-h-screen w-full flex-col items-center justify-center bg-background">
      <div className="h-10 w-10 animate-spin rounded-full border-2 border-muted border-t-primary" />
      <p className="mt-4 text-sm text-muted-foreground">Loading...</p>
    </div>
  );
}

/**
 * V202 强化版错误兜底页（深色工业风，与站点风格一致）
 * - 显示用户可读的错误信息
 * - 提供刷新 / 返回首页 / 清除缓存 三种恢复方式
 * - 不依赖任何 React 组件，纯内联样式，确保在任何错误下都能渲染
 */
function ErrorFallback({ error, resetErrorBoundary }: { error: Error; resetErrorBoundary: () => void }) {
  const navigate = useNavigate();
  const handleClearCacheAndReload = () => {
    try {
      // 清除可能损坏的 localStorage 数据（保留必要配置）
      const keysToKeep = [
        '__app_ledlight_language',
        '__app_ledlight_admin_auth',
        '__app_ledlight_cookie_consent',
        '__app_ledlight_products',
        '__app_ledlight_advantages',
        '__app_ledlight_testimonials',
      ];
      const allKeys: string[] = [];
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.startsWith('__app_ledlight_') && !keysToKeep.includes(key)) {
          allKeys.push(key);
        }
      }
      allKeys.forEach((k) => localStorage.removeItem(k));
    } catch {
      // 忽略
    }
    // 强制刷新绕过缓存
    window.location.reload();
  };

  return (
    <div className="flex min-h-screen w-full items-center justify-center bg-background px-4 py-8">
      <div className="w-full max-w-md rounded-sm border border-border bg-card p-8">
        <div className="mb-6 flex items-center gap-3">
          <div className="flex h-10 w-10 items-center justify-center rounded-sm bg-primary/10 text-primary">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/>
              <line x1="12" y1="9" x2="12" y2="13"/>
              <line x1="12" y1="17" x2="12.01" y2="17"/>
            </svg>
          </div>
          <div>
            <h1 className="text-lg font-semibold text-foreground">Something went wrong</h1>
            <p className="text-sm text-muted-foreground">The page encountered an error</p>
          </div>
        </div>

        <div className="mb-6 rounded-sm border border-border bg-background p-3">
          <p className="font-mono text-xs text-muted-foreground break-all">
            {error?.message || String(error)}
          </p>
        </div>

        <div className="space-y-2">
          <button
            onClick={resetErrorBoundary}
            className="w-full rounded-sm bg-primary px-4 py-2.5 text-sm font-medium text-primary-foreground hover:bg-primary/90 transition-colors"
          >
            Refresh page
          </button>
          <button
            onClick={handleClearCacheAndReload}
            className="w-full rounded-sm border border-border bg-transparent px-4 py-2.5 text-sm font-medium text-foreground hover:bg-muted transition-colors"
          >
            Clear cache and reload
          </button>
          <button
            onClick={() => { navigate('/'); }}
            className="w-full rounded-sm border border-border bg-transparent px-4 py-2.5 text-sm font-medium text-muted-foreground hover:bg-muted hover:text-foreground transition-colors"
          >
            Go to homepage
          </button>
        </div>

        <p className="mt-6 text-center text-xs text-muted-foreground">
          OWELL Industrial
        </p>
      </div>
    </div>
  );
}

/**
 * 额外一层 Class 组件错误边界
 * 用于捕获 ErrorBoundary 自身或其外层可能漏掉的渲染错误
 * （例如 StrictMode 下某些边界情况）
 */
class OuterErrorBoundary extends Component<{ children: ReactNode }, { hasError: boolean; error: Error | null }> {
  constructor(props: { children: ReactNode }) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error) {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error) {
    logger.error('OuterErrorBoundary caught error:', String(error));
  }

  render() {
    if (this.state.hasError && this.state.error) {
      return (
        <ErrorFallback
          error={this.state.error}
          resetErrorBoundary={() => {
            this.setState({ hasError: false, error: null });
            window.location.reload();
          }}
        />
      );
    }
    return this.props.children;
  }
}

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <OuterErrorBoundary>
      <BrowserRouter basename={BASENAME}>
        <ErrorBoundary
          FallbackComponent={ErrorFallback}
          onReset={() => window.location.reload()}
          onError={(error) => {
            logger.error('React ErrorBoundary caught error:', String(error));
          }}
        >
          <Suspense fallback={<GlobalSuspenseFallback />}>
            <App />
          </Suspense>
        </ErrorBoundary>
      </BrowserRouter>
    </OuterErrorBoundary>
  </StrictMode>,
);
