/**
 * 页面级错误边界：捕获后台子页面的渲染错误
 * 防止单个页面崩溃导致整个后台白屏
 */
interface PageErrorBoundaryProps {
  children: ReactNode;
}

interface PageErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
  autoRetryCount: number;
  isRetrying: boolean;
}

class PageErrorBoundary extends Component<PageErrorBoundaryProps, PageErrorBoundaryState> {
  private autoRetryTimer: ReturnType<typeof setTimeout> | null = null;

  constructor(props: PageErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false, error: null, autoRetryCount: 0, isRetrying: false };
  }

  static getDerivedStateFromError(error: Error): PageErrorBoundaryState {
    return { hasError: true, error, autoRetryCount: 0, isRetrying: false };
  }

  componentDidCatch(error: Error): void {
    // 记录错误
    try {
      import('@lark-apaas/client-toolkit-lite').then(({ logger }) => {
        logger.error('[PageErrorBoundary] Page render error:', String(error));
      });
    } catch {
      // ignore
    }

    // 若是 chunk 加载类错误（网络波动/部署新版本后旧 chunk 失效），自动重试
    const isChunkError = this.isChunkLoadError(error);
    if (isChunkError && this.state.autoRetryCount < 2) {
      this.scheduleAutoRetry();
    }
  }

  componentWillUnmount(): void {
    if (this.autoRetryTimer) {
      clearTimeout(this.autoRetryTimer);
      this.autoRetryTimer = null;
    }
  }

  isChunkLoadError(error: Error | null): boolean {
    if (!error) return false;
    const msg = error.message || String(error);
    return (
      msg.includes('Loading chunk') ||
      msg.includes('chunk') ||
      msg.includes('Failed to fetch') ||
      msg.includes('dynamically imported module') ||
      msg.includes('NetworkError')
    );
  }

  scheduleAutoRetry = (): void => {
    const nextRetry = this.state.autoRetryCount + 1;
    const delay = 800 * nextRetry; // 800ms / 1600ms 递增

    this.setState({ isRetrying: true, autoRetryCount: nextRetry });

    this.autoRetryTimer = setTimeout(() => {
      // 重置错误状态让 React 重新渲染子组件（重新触发 lazy import）
      this.setState({ hasError: false, error: null, isRetrying: false });
    }, delay);
  };

  handleReset = (): void => {
    if (this.autoRetryTimer) {
      clearTimeout(this.autoRetryTimer);
      this.autoRetryTimer = null;
    }
    this.setState({ hasError: false, error: null, autoRetryCount: 0, isRetrying: false });
  };

  handleReload = (): void => {
    window.location.reload();
  };

  render() {
    // 自动重试中：显示加载中状态
    if (this.state.isRetrying) {
      return (
        <div className="flex flex-col items-center justify-center py-20 px-6 text-center">
          <div className="size-12 animate-spin rounded-full border-2 border-primary/30 border-t-primary mb-4" />
          <h2 className="text-base font-medium text-foreground mb-1">Retrying...</h2>
          <p className="text-sm text-muted-foreground">
            Loading failed, retrying automatically ({this.state.autoRetryCount}/2)
          </p>
        </div>
      );
    }

    if (this.state.hasError) {
      const isChunkError = this.isChunkLoadError(this.state.error);
      return (
        <div className="flex flex-col items-center justify-center py-20 px-6 text-center">
          <div className="size-16 rounded-full bg-destructive/10 text-destructive flex items-center justify-center mb-4">
            <svg className="size-8" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126zM12 15.75h.007v.008H12v-.008z" />
            </svg>
          </div>
          <h2 className="text-lg font-semibold text-foreground mb-2">Page failed to load</h2>
          <p className="text-sm text-muted-foreground mb-6 max-w-md">
            {isChunkError
              ? 'The page resource could not be loaded. This may be due to a network issue or a recent update.'
              : 'The page encountered an error. Please try refreshing.'}
          </p>
          <div className="flex gap-3">
            <button
              onClick={this.handleReset}
              className="px-4 py-2 rounded-md bg-primary text-primary-foreground text-sm font-medium hover:opacity-90 transition-opacity"
            >
              Retry
            </button>
            <button
              onClick={this.handleReload}
              className="px-4 py-2 rounded-md border border-border text-foreground text-sm font-medium hover:bg-muted transition-colors"
            >
              Refresh Page
            </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

