function AdminSidebar({ footerSettings }: { footerSettings: FooterSettings }) {
  const { adminT, adminLanguage, setAdminLanguage } = useI18n();
  const navigate = useNavigate();
  const location = useLocation();
  const { unreadCount } = useInquiries();
  const handleLogout = () => {
    try {
      localStorage.removeItem(AUTH_KEY);
    } catch {
      // ignore
    }
    toast.success(adminT('admin.loggedOut'));
    navigate('/admin/login', { replace: true });
  };

  const currentLangLabel =
    LANGUAGE_OPTIONS.find((l) => l.code === adminLanguage)?.label || adminLanguage;
  const logoSrc = footerSettings.headerLogo || imgPath('/images/owell-logo.png');

  return (
    <Sidebar collapsible="icon" className="border-r border-sidebar-border">
      <SidebarHeader>
        <div className="flex items-center gap-2 px-2 py-3 group-data-[state=collapsed]:px-0 group-data-[state=collapsed]:justify-center">
           <div className="size-8 shrink-0 overflow-hidden flex items-center justify-center">
               <Image
                 src={logoSrc}
                 alt="OWELL Industrial"
                 width={32}
                 height={32}
                 loading="lazy"
                 decoding="async"
                 className="w-full h-full object-contain bg-transparent"
               />
            </div>
          <div className="flex-1 min-w-0 group-data-[state=collapsed]:hidden">
             <div className="text-sm font-semibold truncate">{adminT('admin.brand.name')}</div>
            <div className="text-xs text-muted-foreground truncate">{adminT('admin.brand.subtitle')}</div>
          </div>
        </div>
      </SidebarHeader>
      <SidebarContent>
          <SidebarGroup className="p-2">
            <SidebarMenu>
              {NAV_ITEMS.map((item) => {
                const Icon = item.icon;
                const label = adminT(item.i18nKey);
                const isActive =
                  item.path === '/admin/dashboard'
                    ? location.pathname === '/admin/dashboard'
                    : location.pathname === item.path ||
                      location.pathname.startsWith(`${item.path}/`);
               return (
                 <SidebarMenuItem key={item.path}>
                   <SidebarMenuButton
                     asChild
                     tooltip={label}
                     isActive={isActive}
                   >
                     <NavLink
                       to={item.path}
                       end={item.path === '/admin/dashboard'}
                       className="flex items-center gap-2"
                     >
                        <Icon className="size-4 shrink-0" />
                        <span className="group-data-[state=collapsed]:hidden flex-1">{label}</span>
                        {item.path === '/admin/inquiries' && unreadCount > 0 && (
                          <span className="group-data-[state=collapsed]:hidden shrink-0 inline-flex items-center justify-center min-w-[18px] h-[18px] px-1 text-[10px] font-bold rounded-full bg-destructive text-destructive-foreground">
                            {unreadCount > 99 ? '99+' : unreadCount}
                          </span>
                        )}
                     </NavLink>
                   </SidebarMenuButton>
                 </SidebarMenuItem>
               );
            })}
            </SidebarMenu>
          </SidebarGroup>
      </SidebarContent>
      <SidebarFooter>
        <div className="space-y-1 p-2">
          {/* 语言切换 */}
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="sm" className="w-full justify-start text-muted-foreground">
                <Languages className="size-4 mr-2 shrink-0" />
                <span className="flex-1 text-left truncate group-data-[state=collapsed]:hidden">
                  {currentLangLabel}
                </span>
                <ChevronDown className="size-3 ml-auto opacity-50 group-data-[state=collapsed]:hidden" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" side="right" className="w-36">
              {LANGUAGE_OPTIONS.map((opt) => (
                <DropdownMenuItem
                  key={opt.code}
                  onClick={() => setAdminLanguage(opt.code)}
                  className={adminLanguage === opt.code ? 'text-primary font-medium' : ''}
                >
                  {opt.label}
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>

          <Button
            variant="ghost"
            size="sm"
            className="w-full justify-start text-muted-foreground hover:text-destructive hover:bg-destructive/10"
            onClick={handleLogout}
          >
            <LogOut className="size-4 mr-2 shrink-0" />
            <span className="group-data-[state=collapsed]:hidden">{adminT('admin.logout')}</span>
          </Button>
        </div>
      </SidebarFooter>
    </Sidebar>
  );
}

export default function AdminLayout() {
  const [isAuth, setIsAuth] = useState<boolean | null>(null);
  const location = useLocation();
  const { adminT } = useI18n();
  const { statusMap, dirtyCount } = useSyncService();
  const { isConfigured } = useGithubConfig();
  const navigate = useNavigate();

  // 🔴 给 body 加 admin-theme 类，让 Dialog/Sheet 等 Portal 渲染的弹窗也能获得浅色主题
  // 注意：此 useEffect 必须放在所有早返回之前，保证 hooks 调用顺序稳定（React error #310 根因）
  useEffect(() => {
    document.body.classList.add('admin-theme');
    return () => {
      document.body.classList.remove('admin-theme');
    };
  }, []);

  // 🔴 后台打开时自动从 GitHub 拉取最新数据
  // 使用独立组件 GithubPullLoader（在 SidebarProvider 内渲染）
  // 好处：拉取逻辑在子组件中，出错不影响主布局；延迟500ms启动不阻塞首屏

  // 计算总体同步状态
  const overallSyncStatus = (() => {
    const statuses = Object.values(statusMap);
    if (statuses.some(s => s === 'syncing')) return 'syncing';
    if (statuses.some(s => s === 'error')) return 'error';
    if (dirtyCount > 0) return 'dirty';
    return 'synced';
  })();

  const syncStatusLabel = {
    synced: 'All synced',
    dirty: `${dirtyCount} unsaved`,
    syncing: 'Syncing...',
    error: 'Sync error',
  }[overallSyncStatus];

  const syncStatusColor = {
    synced: 'text-emerald-600 bg-emerald-50 border-emerald-200',
    dirty: 'text-amber-600 bg-amber-50 border-amber-200',
    syncing: 'text-blue-600 bg-blue-50 border-blue-200',
    error: 'text-red-600 bg-red-50 border-red-200',
  }[overallSyncStatus];
  // 放在顶层早返回之前，保证 hooks 数量稳定
  const { settings: footerSettings } = useFooterSettings();

  useEffect(() => {
    try {
      const auth = localStorage.getItem(AUTH_KEY);
      setIsAuth(auth === 'true');
    } catch {
      setIsAuth(false);
    }
  }, [location.pathname]);

  if (isAuth === null) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (!isAuth) {
    return <Navigate to="/admin/login" replace />;
  }

  return (
    <SidebarProvider className="admin-theme">
      <AdminSidebar footerSettings={footerSettings} />
      <SidebarInset className="flex flex-col min-w-0 overflow-x-hidden bg-[#f5f7fa]">
        {/* Admin Topbar */}
        <header className="sticky top-0 z-40 h-14 border-b border-border/40 bg-[#ffffff]/80 backdrop-blur-md flex items-center justify-between px-4">
          <div className="flex items-center gap-3">
            <SidebarTrigger className="md:hidden" />
            <h1 className="text-sm font-semibold text-foreground">
               {adminT('admin.brand.name')}
            </h1>
          </div>
          <div className="flex items-center gap-3">
            {/* GitHub 同步状态 */}
            {isConfigured ? (
              <button
                onClick={() => navigate('/admin/github-sync')}
                className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium border transition-colors hover:opacity-80 ${syncStatusColor}`}
                title={syncStatusLabel}
              >
                {overallSyncStatus === 'syncing' && (
                  <span className="size-3 rounded-full border-2 border-current border-t-transparent animate-spin" />
                )}
                {overallSyncStatus === 'synced' && (
                  <span className="size-3 rounded-full bg-current opacity-70" />
                )}
                {overallSyncStatus === 'dirty' && (
                  <span className="size-3 rounded-full bg-current opacity-70" />
                )}
                {overallSyncStatus === 'error' && (
                  <span className="size-3">!</span>
                )}
                <span className="hidden sm:inline">{syncStatusLabel}</span>
              </button>
            ) : (
              <button
                onClick={() => navigate('/admin/github-sync')}
                className="flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium border border-muted-foreground/30 text-muted-foreground hover:text-foreground hover:border-foreground/30 transition-colors"
                title="Configure GitHub sync"
              >
                <Github className="size-3.5" />
                <span className="hidden sm:inline">Sync off</span>
              </button>
            )}
            <Lightbulb className="size-4 text-primary" />
            <span className="text-xs text-muted-foreground">v1.0</span>
          </div>
        </header>

        <main className="flex-1 w-full overflow-y-auto p-4 md:p-6 lg:p-8">
          {/* 自动从 GitHub 拉取最新数据（纯副作用组件，不出现在 UI 中） */}
          <GithubPullLoader />

          <Suspense
            fallback={
              <div className="flex flex-col items-center justify-center py-24">
                <div className="size-8 animate-spin rounded-full border-2 border-primary/30 border-t-primary mb-4" />
                <p className="text-sm text-muted-foreground">Loading admin panel...</p>
                <p className="text-xs text-muted-foreground/70 mt-1">
                  This may take a moment on first load
                </p>
              </div>
            }
          >
            <PageErrorBoundary>
              <Outlet />
            </PageErrorBoundary>
          </Suspense>
        </main>
      </SidebarInset>
    </SidebarProvider>
  );
}
